local config = {
  ui_story_2001_1_X1_dialog_content = "<color=#e8d9bb>Tanah tandus di pedesaan Lumopolis</color>",
  ui_story_2001_1_X2_dialog_content = "<color=#e8d9bb>Rombongan kendaraan berpacu gila-gilaan dalam awan debu, dengan suara radio dan mesin yang menggelegar begitu keras dari jauh ke dekat, hingga bendera cerah Rediesel berkibar di cakrawala.</color>",
  ui_story_2001_1_1_dialog_content = "Ha ha, kita menang banyak hari ini! Sudah waktunya kita mendapatkan yang besar seperti Lumopolis Caravan!",
  ui_story_2001_1_2_dialog_content = "Sekarang tinggal perayaannya... Woo!",
  ui_story_2001_1_3_dialog_content = "Hanya perasaanku saja atau kota di depan kita memang makin besar...?",
  ui_story_2001_1_4_dialog_content = "Kamu yakin kita tidak bergerak menuju arah yang salah, Brock?",
  ui_story_2001_1_5_dialog_content = "Hah? Apa maksudmu? Aku melihat peta terus, kok!",
  ui_story_2001_1_6_dialog_content = "Lihat, bukankah tertulis \"3 mil di utara reruntuhan\" di sini? Hmm... Apa nama reruntuhannya...",
  ui_story_2001_1_7_dialog_content = "Anu, Brock... Jangan-jangan... Ehem... Tahu, 'kan...",
  ui_story_2001_1_8_dialog_content = "<size=45>Kau membaca petanya terbalik?</size>",
  ui_story_2001_1_9_dialog_content = "<size=45>Haaah? Sialan, ide siapa ini membuat peta yang tak bisa dibaca oleh siapa pun?!</size>",
  ui_story_2001_1_10_dialog_content = "Kenapa aku berputar-putar entah di mana ini dengan selembar kertas tak berguna?!",
  ui_story_2001_1_11_dialog_content = "Eh, karena kamu menginjak dan memecahkan suar Loose Screws saat kalian bertarung tadi?",
  ui_story_2001_1_12_dialog_content = "Diam, siapa yang tanya! Mereka seharusnya membuat benda itu lebih kuat!",
  ui_story_2001_1_13_dialog_content = "Wah! Wrecker, sebelah sana! Ada orang menuju ke sini!",
  ui_story_2001_1_14_dialog_content = "Tolong kerja samanya dan hentikan kendaraan kalian untuk pemeriksaan oleh Lumopolis! Aku ulangi, tolong hentikan kendaraan kalian!",
  ui_story_2001_1_15_dialog_content = "Itu Lumopolis <color=#FFB400>Patrol</color>! Mereka benar-benar cepat, dan kabar buruknya, jumlah mereka ada banyak...",
  ui_story_2001_1_16_dialog_content = "Huh! Waktu yang tepat bagiku untuk melampiaskannya pada para pecundang itu!",
  ui_story_2001_1_17_dialog_content = "Tunggu, itu...! Buronan terlihat di antara para tersangka, memanggil bantuan...",
  ui_story_2001_1_18_dialog_content = "Astaga, hanya satu serangan bisa menjatuhkannya... Semuanya, tetap siaga, kepung target!",
  ui_story_2001_2_1_dialog_content = "Apa? Cuma segini saja, nih? Aku bisa menaklukkan kalian semua sendiri!",
  ui_story_2001_2_2_dialog_content = "Betapa mengecewakan. Kalian tidak punya kru yang lebih kuat?",
  ui_story_2001_2_3_dialog_content = "B-Brock!",
  ui_story_2001_2_4_dialog_content = "Apa! Hei, kenapa kau luka-luka?",
  ui_story_2001_2_5_dialog_content = "Ini karena orang-orang dari Lumopolis itu... Mereka menyerang dari arah lain dan menahan barang-barang kami. Pemimpin mereka...*batuk*... Berhati-hatilah...",
  ui_story_2001_2_6_dialog_content = "Mengerti. Sst, berhenti bicara, kau terluka!",
  ui_story_2001_2_7_dialog_content = "Siapa yang berani menjarah Rediesel Wrench?! Ini akan menjadikanku bahan tertawaan! Tidak, aku harus mengambil kembali barang-barang kita!",
  ui_story_2001_2_8_dialog_content = "Kalian yang masih bisa bergerak, lindungi aku. Akan kugunakan teknologi baru yang sudah disiapkan untuk kita!",
  ui_story_2001_2_9_dialog_content = "<color=#e8d9bb>Beberapa petir menyambar area di depan Brock, menciptakan ledakan yang memekakkan telinga sebelum dia bisa bereaksi, petir ini bisa dengan mudah membakarnya hingga garing.</color>",
  ui_story_2001_2_10_dialog_content = "Sepertinya kamu cukup handal... Kamu pasti pemimpin pasukan dari Lumopolis.",
  ui_story_2001_2_11_dialog_content = "Bukankah Tuanmu mengajarimu untuk tidak mengurusi barang orang lain?!",
  ui_story_2001_2_12_dialog_content = "...",
  ui_story_2001_2_13_dialog_content = "<color=#e8d9bb>Brock tidak mendapat jawaban kecuali napas berat dari bawah topeng lawannya ini dan suara mendesis dari medan elektro.</color>",
  ui_story_2001_2_14_dialog_content = "Hei! Jangan meremehkanku!",
  ui_story_2001_2_15_dialog_content = "Baiklah! Tunjukkan kemampuanmu padaku!",
  ui_story_2001_2_16_dialog_content = "...",
  ui_story_2001_2_17_dialog_content = "Hah, boleh juga, sepertinya tidak semua orang Lumopolis itu payah.",
  ui_story_2001_2_18_dialog_content = "Karena kau sudah menyerang pasukanku, aku juga akan melukaimu agar kita seri!",
  ui_story_2001_2_19_dialog_content = "...",
  ui_story_2001_2_20_dialog_content = "Kami sudah memasukkan barang-barang dan anggota yang terluka, Brock. Kita harus pergi dari sini!",
  ui_story_2001_2_21_dialog_content = "Baiklah! Sebaiknya kau berterima kasih pada bintang keberuntunganmu aku tidak...",
  ui_story_2001_2_22_dialog_content = "<color=#e8d9bb>Sinar lain melesat melewati Brock, menyerempet ujung hidungnya, meninggalkan bekas di tanah beberapa inci di belakangnya.</color>",
  ui_story_2001_2_23_dialog_content = "<color=#e8d9bb>Brock memperhatikan beberapa orang berpakaian sama muncul di sebelah sosok bertopeng itu—</color>",
  ui_story_2001_2_24_dialog_content = "Ahh! Maaf, maaf! Gara-gara aku semuanya jadi kalah!",
  ui_story_2001_2_25_dialog_content = "Kamu baik-baik saja, <color=#FFB400>Michael</color> kecil? Aku akan mengobatimu sekarang juga!",
  ui_story_2001_2_26_dialog_content = "Ada apa dengan bangsawan tua aneh di Lumopolis, mengirim gadis-gadis kecil kurus untuk bertempur?",
  ui_story_2001_2_27_dialog_content = "Aku tidak tertarik bertempur dengan anak-anak, tapi karena mereka yang memulainya, aku yang akan menyelesaikannya!",
  ui_story_2001_2_28_dialog_content = "Kalian semua enyahlah agar aku bisa pamer! Dan jangan habiskan semua minumannya sebelum aku kembali!",
  ui_story_2001_2_29_dialog_content = "Kami akan mengejar para bandit itu, <color=#FFB400>Madam Carleen</color>...",
  ui_story_2001_2_30_dialog_content = "Tak perlu.",
  ui_story_2001_2_31_dialog_content = "Michael, Raphael, dan patroli yang lain, tetap siaga.",
  ui_story_2001_2_32_dialog_content = "Abaikan tikus-tikus itu dan fokus pada ancaman yang lebih besar.",
  ui_story_2001_2_33_dialog_content = "Hah, matamu tajam juga. Maksudku, bagaimanapun juga, AKULAH komandan kedua dari Rediesel Wrench! Kau hanya datang untuk menerima sendiri serangan ini... Arrrgh!",
  ui_story_2001_2_34_dialog_content = "(Apa yang terjadi? Kenapa tanahnya... Apa aku kalah?)",
  ui_story_2001_2_35_dialog_content = "...",
  ui_story_2001_2_36_dialog_content = "(Apa yang dilakukan wanita bertopeng itu padaku? Aku tak bisa bergerak...!)",
  ui_story_2001_2_37_dialog_content = "Bagus sekali, Michael.",
  ui_story_2001_2_38_dialog_content = "Aku adalah Kapten Carleen dari Guardian. Brock dari Rediesel Wrench, dengan ini aku menangkapmu!",
  ui_story_2001_3_1_dialog_content = "Kamu sudah dengar? Para Guardian menangkap penjahat dari Rediesel Wrench lagi, bahkan sepertinya kali ini yang ditangkap adalah komandan kedua.",
  ui_story_2001_3_2_dialog_content = "Ya, itu jauh lebih baik daripada menangkap sekelompok prajurit tak berguna.",
  ui_story_2001_3_3_dialog_content = "Tunggu hingga perayaannya selesai. Ini akan menjadi akhir bagi para pecundang itu...",
  ui_story_2001_3_4_dialog_content = "(Di mana aku?)",
  ui_story_2001_3_5_dialog_content = "Aduh, aduh, aduh! Hei, sepertinya aku masih hidup!",
  ui_story_2001_3_6_dialog_content = "Cih, di mana mereka terus mendapatkan orang-orang aneh yang bekerja dengan becus...? Aku juga penasaran apakah orang-orang bodoh yang berisik itu bisa lolos...",
  ui_story_2001_3_7_dialog_content = "Hah! Dan aku penasaran siapa pecundang songong ini!",
  ui_story_2001_3_8_dialog_content = "Siapa yang kamu sebut pecundang sombong? Aku mungkin sedikit lengah hari ini, tapi jika orang itu tidak menyergapku dari belakang... Tunggu, siapa yang berbicara di sana?!",
  ui_story_2001_3_9_dialog_content = "<size=40>Lama tak jumpa, Brock.</size>",
  ui_story_2001_3_10_dialog_content = "<color=#e8d9bb>Seorang wanita melangkah keluar dari bayangan, menatap Brock dengan licik.</color>",
  ui_story_2001_3_11_dialog_content = "<color=#e8d9bb>Brock mencium bau mesiu yang tajam tapi familier lalu menyipitkan mata padanya dalam cahaya redup.</color>",
  ui_story_2001_3_12_dialog_content = "<color=#FFB400>Jona</color>? Kenapa kamu di sini?",
  ui_story_2001_3_13_dialog_content = "Eh, kita ada di mana, sih?",
  ui_story_2001_3_14_dialog_content = "Hukuman mati Lumopolis. Hmm, tapi kenapa aku bisa ada di sini. Sebenarnya, aku sudah lupa...",
  ui_story_2001_3_15_dialog_content = "Sepertinya aku berada di sebuah penginapan terpencil yang sudah bobrok, mengikuti kontes minum dengan seseorang yang tak tahu apa-apa, lalu tahu-tahu sudah terbangun di sini.",
  ui_story_2001_3_16_dialog_content = "Huh, Bounty Hunter atau mata-mata Lumo mungkin menghasilkan banyak uang dariku.",
  ui_story_2001_3_17_dialog_content = "Tapi jujur saja, mengingat berapa banyak uang yang mereka sayembarakan untuk kepalaku, bahkan aku akan mencoba mengambilnya sendiri jika bisa!",
  ui_story_2001_3_18_dialog_content = "<color=#e8d9bb>Jona menceritakan penderitaannya seolah-olah mengejek orang lain, ejekannya bergema di dinding sel.</color>",
  ui_story_2001_3_19_dialog_content = "Pantas saja kau menghilang setelah misi terakhir... Lumopolis sialan, jika saja pasukanku bisa mendapatkan informasi lebih cepat! Aduh!",
  ui_story_2001_3_20_dialog_content = "Hati-hati. Itu luka baru, 'kan? Luka itu akan robek lagi jika kau tak hati-hati.",
  ui_story_2001_3_21_dialog_content = "Pelayanan di sini lumayan, dan tidak ada Sinsa yang mengomel tentang segalanya, jadi sebenarnya ini tidak terlalu buruk.",
  ui_story_2001_3_22_dialog_content = "Tapi bermalas-malasan... tidak, maksudku, dikurung tanpa melakukan apa-apa makin membosankan.",
  ui_story_2001_3_23_dialog_content = "Ditambah lagi, menjejalkan dua kader Rediesel Wrench dengan hukuman mati di sel yang sama terasa sangat menyesakkan. Aku tak ingin satu sel dengan orang bodoh.",
  ui_story_2001_3_24_dialog_content = "Apa yang kamu gumamkan di sana? Dan kamu baru saja dengan santainya menghina...?",
  ui_story_2001_3_25_dialog_content = "Omong-omong...",
  ui_story_2001_3_26_dialog_content = "<color=#e8d9bb>Jona mengeretakkan leher dan buku-buku jarinya, dan sebelum Brock bisa bereaksi,</color>",
  ui_story_2001_3_27_dialog_content = "<size=45><color=#e8d9bb>sebuah lubang besar baru saja diledakkan di dinding.</color></size>",
  ui_story_2001_3_28_dialog_content = "Aku akan membebaskanmu, jadi sebaiknya ikuti aku!",
  ui_story_2001_4_1_dialog_content = "Ledakan di Maximum Security Compound, kemungkinan pembobolan! Personel keamanan segera datang ke area...",
  ui_story_2001_4_2_dialog_content = "Argh!",
  ui_story_2001_4_3_dialog_content = "Itu polisi Lumo yang ke lima puluh satu. Mereka mudah diatasi, dibandingkan dengan mekanisme keamanan yang menyebalkan itu...",
  ui_story_2001_4_4_dialog_content = "<color=#e8d9bb>Brock sengaja mengucapkan itu dengan lantang sambil melirik Jona, yang sepertinya tidak memperhatikan.</color>",
  ui_story_2001_4_5_dialog_content = "Hei, bagaimana denganmu?",
  ui_story_2001_4_6_dialog_content = "Hah? Ini kompetisi? Aku tidak menghitung sama sekali... Anggap saja lima puluh.",
  ui_story_2001_4_7_dialog_content = "Jona, kau meremehkanku, ya?",
  ui_story_2001_4_8_dialog_content = "Aku tak akan pernah meremehkan, terutama \"komandan kedua dari Rediesel\"! Tinggal sedikit lagi hingga kau bisa menggulingkan Sinsa dan meraih posisi teratas, 'kan?",
  ui_story_2001_4_9_dialog_content = "Da-dari mana kau tahu itu? Itu hanya kebohongan untuk mengulur waktu agar pasukan kita bisa pergi!",
  ui_story_2001_4_10_dialog_content = "Yah, terserah. Tak ada yang menertawakan aspirasimu, meskipun skormu 0 lawan 728 dengan 3 kali seri melawannya...",
  ui_story_2001_4_11_dialog_content = "Hmm, sepertinya kita sudah berada di batas luar Lumopolis sekarang.",
  ui_story_2001_4_12_dialog_content = "Oh. Apa artinya itu?",
  ui_story_2001_4_13_dialog_content = "Itu pesawat Lumo Patrol. Sepertinya kita berada di <color=#FFB400>Shuttle Hub</color> kecil.",
  ui_story_2001_4_14_dialog_content = "Boleh juga. Pesawat ini sudah mengejarku cukup lama, sudah saatnya aku mengendarainya!",
  ui_story_2001_4_15_dialog_content = "Hei, tunggu...",
  ui_story_2001_4_16_dialog_content = "Huh... Kenapa harus kita yang menemukan mereka?",
  ui_story_2001_4_17_dialog_content = "Harusnya sekarang adalah waktu tidur siangku. Jadwal istirahat yang kacau benar-benar berujung pada kejadian yang menyebalkan...",
  ui_story_2001_4_18_dialog_content = "Hidupmu akan segera berakhir, mengakhiri rasa sakitmu. Kenapa melarikan diri?",
  ui_story_2001_4_19_dialog_content = "Kamu bisa mengucapkan selamat tinggal pada semua ini, dan aku benar-benar akan merasa iri akan itu.",
  ui_story_2001_4_20_dialog_content = "Sial. Ada yang datang, Jona! Apakah dua orang ini...?",
  ui_story_2001_4_21_dialog_content = "Guardian Angel of the Knight! Ternyata cerita-cerita itu nyata...",
  ui_story_2001_4_22_dialog_content = "Jangan tertipu oleh penampilannya, mereka bahkan...",
  ui_story_2001_4_23_dialog_content = "... lebih imut daripada di cerita-cerita itu!",
  ui_story_2001_4_24_dialog_content = "Hah?",
  ui_story_2001_4_25_dialog_content = "Melihat bagaimana Lumopolis menyia-nyiakan sumber daya yang melimpah dari peradaban kuno dan melayani para elite di awan, kukira Lumopolis hanyalah lubang pesta pora.",
  ui_story_2001_4_26_dialog_content = "Aku benar-benar tidak mengira Knight mereka beranggotakan para Battle Maiden yang cantik! Sayang sekali...",
  ui_story_2001_4_27_dialog_content = "Halo, yang kita hadapi ini musuh, 'kan? Aku tak peduli apakah mereka ini gadis cantik atau setan dari neraka...",
  ui_story_2001_4_28_dialog_content = "Akan jarang sekali bagimu untuk bisa berbicara dengan gadis-gadis cantik, Brock. Kau harus menghargai kesempatan ini.",
  ui_story_2001_4_29_dialog_content = "Bu-bukan urusanmu! Jona! Sepertinya mereka akan menyerang!",
  ui_story_2001_4_30_dialog_content = "<color=#e8d9bb>Serangan mereka melewati Brock, menghancurkan pesawat dan harapan untuk melarikan diri dengan kendaraan itu.</color>",
  ui_story_2001_4_31_dialog_content = "Sialan, pesawatnya...!",
  ui_story_2001_4_32_dialog_content = "Hihi! Tamu yang bersemangat sekali, ya, Uriel sayang? Bisakah aku... bersenang-senang sedikit lagi...?",
  ui_story_2001_4_33_dialog_content = "Cukup, Gabriel. Sebelum lebih banyak penjaga tiba...",
  ui_story_2001_4_34_dialog_content = "... Mari kita kirim mereka ke... peristirahatan abadi.",
  ui_story_2001_4_35_dialog_content = "Hahahahahaha!",
  ui_story_2001_4_36_dialog_content = "Baiklah, sudah lama aku tak beraksi! Jangan hanya berdiri di sana, kalian berdua juga jangan sampai tertinggal!",
  ui_story_2001_4_37_dialog_content = "Heh, heh...",
  ui_story_2001_4_38_dialog_content = "Ya, mudah sekali kau mengatakannya... Apa? Kalian...!",
  ui_story_2001_4_39_dialog_content = "<color=#e8d9bb>Dua sosok familier turun lagi di hadapan Brock yang melemah.</color>",
  ui_story_2001_4_40_dialog_content = "...",
  ui_story_2001_4_41_dialog_content = "Tunggu, tunggu aku, Michael! Lukamu baru saja sembuh, berlari sekencang itu akan...",
  ui_story_2001_4_42_dialog_content = "Kau mungkin perlu memeriksakan matamu... Jelas-jelas dia seorang gadis.",
  ui_story_2001_4_43_dialog_content = "Yessss! Hari ini pasti hari keberuntunganku! Keempat malaikat di satu tempat!",
  ui_story_2001_4_44_dialog_content = "Hari kiamat, maksudmu? Mengalahkan keempatnya sekaligus dengan hanya berdua saja...",
  ui_story_2001_4_45_dialog_content = "Biar kuurus, Jona! Pergi dan cari apakah ada yang lainnya di sekitar sini...",
  ui_story_2001_4_46_dialog_content = "Simpan pidato suram dan serammu untuk lain waktu, ya? Sudah kubilang aku akan mengeluarkanmu dari sini, jadi akan memalukan jika aku tidak melakukannya.",
  ui_story_2001_4_47_dialog_content = "Perjalanan ini tidak sia-sia. Sesuai yang kuharapkan dari Lumopolis!",
  ui_story_2001_4_48_dialog_content = "Sekarang aku paham kenapa begitu banyak orang bodoh yang putus asa berkumpul di sini berharap untuk terpilih suatu hari nanti.",
  ui_story_2001_4_49_dialog_content = "Sayangnya, jauh lebih mudah untuk pergi.",
  ui_story_2001_4_50_dialog_content = "<size=45>Selamat tinggal, malaikat-malaikat kecil!</size>",
  ui_story_2001_4_51_dialog_content = "<color=#e8d9bb>Jona meraih Brock dan <color=#FFB400>melompat</color></color> dari tepi Hub.",
  ui_story_2001_4_52_dialog_content = "<color=#e8d9bb>Hilangnya beban yang tiba-tiba ini membuat merinding hingga ke sel-sel mereka.</color>",
  ui_story_2001_4_53_dialog_content = "Masih banyak yang bisa diperbaiki dari hidangan dan penginapannya, tapi layanannya patut diacungi jempol! Sampai jumpa lagi!",
  ui_story_2001_4_54_dialog_content = "Arghhhhh!",
  ui_story_2001_4_55_dialog_content = "<size=45>Kita akan mati–!!</size>",
  ui_story_2001_4_56_dialog_content = "<color=#e8d9bb>Brock menjerit dan merasa sesak saat penglihatannya kabur dan menjadi gelap...</color>",
  ui_story_2001_5_1_dialog_content = "...",
  ui_story_2001_5_2_dialog_content = "Hei, apakah kau akan segera berhenti bersikap seperti itu? Aku sudah minta maaf, 'kan?",
  ui_story_2001_5_3_dialog_content = "Aku tidak...",
  ui_story_2001_5_4_dialog_content = "Pengecut sekali. Aku belum pernah mendengar jeritan menyedihkan seperti itu sebelumnya.",
  ui_story_2001_5_5_dialog_content = "Aku takut ketinggian! Dan siapa pula yang cukup gila untuk melompat turun dari Lumopolis?!",
  ui_story_2001_5_6_dialog_content = "Kamu harus mengejutkan dirimu sendiri sebelum bisa mengejutkan musuh.",
  ui_story_2001_5_7_dialog_content = "Mereka pasti tidak memperkirakan itu, 'kan? Anggap saja ini sebagai improvisasi Rediesel Wrench! Hah!",
  ui_story_2001_5_8_dialog_content = "Improvisasi? Jadi, omonganmu serius saat kamu bilang kita mendarat dengan selamat, berkat kekuatan dari rekoil senjata api?",
  ui_story_2001_5_9_dialog_content = "Rekoil mungkin ada hubungannya dengan itu, tentu saja, tapi sebagian besar...",
  ui_story_2001_5_10_dialog_content = "Lumina-mu yang kuat, meskipun melemah karena borgol itu?",
  ui_story_2001_5_11_dialog_content = "Sebagian besar berkat KEBERUNTUNGAN! Wahahaha!",
  ui_story_2001_5_12_dialog_content = "Kaulah orang pertama yang akan kubunuh begitu aku mengambil alih posisi Sinsa.",
  ui_story_2001_5_13_dialog_content = "Serius? Aku tak sabar, kalau begitu. Tentu saja, asalkan aku bisa hidup cukup lama hingga hal itu akhirnya terjadi.",
  ui_story_2001_5_14_dialog_content = "Bagaimana kalau kita pergi ke arah Umbraton dan minum-minum? Siapa tahu kita juga bisa dapat tumpangan...",
  ui_story_2001_5_15_dialog_content = "Hei, lihat ke sebelah sana! Itu seperti bendera <color=#FFB400>Loose Screws</color>!",
  ui_story_2001_5_16_dialog_content = "Sepertinya kalian berdua bersenang-senang, dan Jona bahkan kelihatan tambah gemuk.",
  ui_story_2001_5_17_dialog_content = "Tapi yang membuatku kesal, kalian tidak mengajakku di pertempuran yang sangat menyenangkan itu di Lumopolis!",
  ui_story_2001_5_18_dialog_content = "Heh, kami bahkan bertemu keempat malaikat itu sekaligus! Benar 'kan, Brock!",
  ui_story_2001_5_19_dialog_content = "Eh, ya...",
  ui_story_2001_5_20_dialog_content = "Ada apa dengan pria ini, tidak sarapan tadi pagi?",
  ui_story_2001_5_21_dialog_content = "Sudahlah. Bos besar mengirimku keluar untuk menjemput kalian, jadi asalkan aku membawa kalian kembali dalam kondisi utuh...",
  ui_story_2001_5_22_dialog_content = "Sinsa sesekali bertingkah seperti dia yang paling berkuasa, rupanya.",
  ui_story_2001_5_23_dialog_content = "Tepatnya, semua ingin makan di restoran ramen di Umbraton, jadi sekaligus melihat apakah bisa menjemput kalian karena sekalian lewat.",
  ui_story_2001_5_24_dialog_content = "Tapi omong-omong, berdasarkan pengamatan teknologi, tempat ini harusnya akan dipenuhi dengan Eclipsite sebentar lagi.",
  ui_story_2001_5_25_dialog_content = "Sebentar lagi?",
  ui_story_2001_5_26_dialog_content = "Itu kata Odi tadi saat aku pergi.",
  ui_story_2001_5_27_dialog_content = "Berarti pertunjukan hampir dimulai?",
  ui_story_2001_5_28_dialog_content = "Kalau begitu, kita harus pergi! Kondisi kami sedang kurang fit untuk berhadapan dengan Eclipsite sekarang...",
  ui_story_2001_5_29_dialog_content = "Sekarang kita sudah jadi pengecut?",
  ui_story_2001_5_30_dialog_content = "Tidak, ini namanya akal sehat, akal sehat! Bukankah Lumopolis sedang mengejar kita juga?",
  ui_story_2001_5_31_dialog_content = "Oh, mereka... Mereka sudah di sini dan menunggu untuk menyergap.",
  ui_story_2001_5_32_dialog_content = "Apa?!",
  ui_story_2001_5_33_dialog_content = "Baiklah, kalian para Whitehead bisa keluar sekarang. Eclipsite sudah siap menyerang, jadi mari kita selesaikan ini dengan cepat, oke?",
  ui_story_2001_6_1_dialog_content = "Kemarilah. Akan kubuat kalian semua terpental!",
  ui_story_2001_6_2_dialog_content = "Brock cepat sekali sembuhnya... Hei, hati-hati ada pasir isap...!",
  ui_story_2001_6_3_dialog_content = "Ups. Terlambat.",
  ui_story_2001_6_4_dialog_content = "Kamu baru saja selesai \"liburan\" dan masih ingin beristirahat sekarang, Jona?",
  ui_story_2001_6_5_dialog_content = "<color=#e8d9bb>Suhunya tiba-tiba menurun drastis, membuat semua orang merinding.</color>",
  ui_story_2001_6_Q1_dialog_content = "Yah, sepertinya kita terjebak dengan Eclipsite. Saatnya untuk serius.",
  ui_story_2001_6_Q2_dialog_content = "Eclipsite? Grr... Mengganggu sekali! Kalau saja para Whitehead ini tidak memperlambat kita...",
  ui_story_2001_6_Q3_dialog_content = "Tunggu dulu, bukankah pertempuran besar akan merusak lingkungan sekitar... dan restoran ramen kita juga?",
  ui_story_2001_6_Q4_dialog_content = "Kau perlu mengatur prioritasmu, Regina.",
  ui_story_2001_6_6_dialog_content = "Coba lihat ke sana. Apa itu yang sedang mendekati kita di antara para Eclipsite?",
  ui_story_2001_6_7_dialog_content = "Dari sini saja aku bisa tahu bahwa dia akan menjadi lawan yang tangguh...",
  ui_story_2001_6_8_dialog_content = "Aahhhhhh!",
  ui_story_2001_6_9_dialog_content = "<color=#e8d9bb>Sementara itu,</color>",
  ui_story_2001_6_10_dialog_content = "<color=#e8d9bb>para Guardian dari Lumopolis, yang sedang memburu Brock, malah terlibat dalam pertempuran dengan gerombolan Eclipsite.</color>",
  ui_story_2001_6_11_dialog_content = "Tetap di tempat! Angel di depan, diikuti oleh skuad 3 dan 7!",
  ui_story_2001_6_12_dialog_content = "Yang lain tetap siaga dan tunggu perintahku!",
  ui_story_2001_6_13_dialog_content = "Kapten! Target telah menembus masuk ke formasi dan bergerak menuju permukiman!",
  ui_story_2001_6_14_dialog_content = "Musuh telah memblokir pasukan kita! Kami juga kehilangan komunikasi karena adanya gangguan!",
  ui_story_2001_6_15_dialog_content = "Kapten Carleen, jika terus seperti ini...",
  ui_story_2001_6_16_dialog_content = "Wah, wah, pesta yang meriah sekali! Boleh kami bergabung? Boleh, ya, putri Guardian?",
  ui_story_2001_6_17_dialog_content = "Yah, karena aku ketinggalan kesenangan di atas, aku tak akan melewatkan ini!",
  ui_story_2001_6_18_dialog_content = "Beraninya kau menunjukkan diri di hadapanku?",
  ui_story_2001_6_19_dialog_content = "Sudah marah-marahnya, Sayang. Kita tak ada waktu untuk saling menggoda sekarang.",
  ui_story_2001_6_20_dialog_content = "Apa-apaan kau...!",
  ui_story_2001_6_21_dialog_content = "Hah! Orang besar itu jatahku kalau kau terus mengoceh!",
  ui_story_2001_6_22_dialog_content = "Bermimpilah, itu pialaku!",
  ui_story_2001_6_23_dialog_content = "Hei, kalian mendahului! Itu curang! Kembali ke sini!",
  ui_story_2001_6_24_dialog_content = "<color=#e8d9bb>Keduanya bercanda saat mereka dengan ceroboh bergabung dalam pertempuran antara Eclipsite dan Guardian...</color>",
  ui_story_2001_6_25_dialog_content = "C-captain, sepertinya ada celah. Eclipsite telah tersebar karena mereka berdua...",
  ui_story_2001_6_26_dialog_content = "<color=#e8d9bb>Melihat para bandit itu memecah gerombolan Eclipsite, Carleen berbalik dan memberi perintah kepada para Guardian.</color>",
  ui_story_2001_6_27_dialog_content = "Semuanya serang! Hancurkan barisan mereka!",
  ui_story_2001_6_28_dialog_content = "Jangan menjebakku, Tuan Putri.",
  ui_story_2001_6_29_dialog_content = "Harusnya aku yang bilang begitu, dasar teroris! Terima seranganku!",
  ui_story_2001_6_30_dialog_content = "Fiuh! Sudah tak ada lagi Eclipsite. Sepertinya sudah cukup kali ini dan Lumopolis bahkan tidak mendapatkan nilai lulus, jika dibulatkan.",
  ui_story_2001_6_31_dialog_content = "Semua unit, segera hitung jumlah korban dan mulai protokol respons pertama. Aku ingin laporan hari ini. Ganti.",
  ui_story_2001_6_32_dialog_content = "Sepertinya jadi kapten repot juga. Aku tak akan mengganggumu. Aku pergi dulu, ya!",
  ui_story_2001_6_33_dialog_content = "Berhenti.",
  ui_story_2001_6_34_dialog_content = "Jona, kader Rediesel Wrench, atas tindakan pelarian diri dari penjara dan menyebabkan kerugian besar di Lumopolis, dengan ini aku...",
  ui_story_2001_6_35_dialog_content = "Kau akan menangkapku? Kamu akan selalu membosankan jika terus bersikap angkuh seperti itu, Tuan Putri.",
  ui_story_2001_6_36_dialog_content = "Penjahat yang congkak, kau harus membayar banyak atas kekurangajaranmu...",
  ui_story_2001_6_37_dialog_content = "<color=#e8d9bb>Sebelum Carleen menyelesaikan kalimatnya, tanah mulai bergetar berirama seolah-olah ada sesuatu yang mendekat. Dia dengan sigap mengambil posisi bertarung, lalu melihat...</color>",
  ui_story_2001_6_38_dialog_content = "<size=45>Hei.</size>",
  ui_story_2001_6_39_dialog_content = "Kenapa lama sekali, Bung?",
  ui_story_2001_6_40_dialog_content = "Haha, tak ada yang bisa membangunkanku dari tidur siangku.",
  ui_story_2001_6_41_dialog_content = "Kau Sinsa? Dari Rediesel Wrench...",
  ui_story_2001_6_42_dialog_content = "Betul sekali, aku pemimpin mereka. Terima kasih sudah merawat mereka, orang-orang Lumopolis.",
  ui_story_2001_6_43_dialog_content = "Kalian kira kalian bisa pergi? Enak saja!",
  ui_story_2001_6_44_dialog_content = "Jangan repot-repot, putri mungil. Urus dulu para prajuritmu. Tak usah bersedih, kita akan berjumpa lagi saat aku mulai rindu makanan di Lumopolis.",
  ui_story_2001_6_45_dialog_content = "Berhenti!",
  ui_story_2001_6_46_dialog_content = "<color=#e8d9bb>Carleen mencoba mengejar, tetapi entah mengapa kakinya menjadi seberat timah dan dia hanya bisa melihat geng Rediesel Wrench itu melenggang pergi....</color>",
  ui_story_2001_6_47_dialog_content = "Aku sudah mencarimu ke mana-mana, Carleen! Harusnya kau tak lari saat terluka begitu!",
  ui_story_2001_6_48_dialog_content = "Memang apa hubungannya dengan tinggi badan?",
  ui_story_2001_6_49_dialog_content = "Hmm? Apa katamu?",
  ui_story_2001_6_50_dialog_content = "Tak apa. Ayo pulang.",
  ui_story_2001_6_51_dialog_content = "Tapi aku janji, akan membalas ini.",
  ui_story_2002_1_1_dialog_content = "...",
  ui_story_2002_1_2_dialog_content = "... Hah?",
  ui_story_2002_1_3_dialog_content = "Aduh! Ekorku!!",
  ui_story_2002_1_4_dialog_content = "<color=#e8d9bb>Undercity tetap tenang selagi mereka beristirahat. Sharona terbangun dari mimpinya dan merasa ada seseorang—\natau sesuatu—yang menyentuh ekornya...</color>",
  ui_story_2002_1_5_dialog_content = [[
<color=#e8d9bb>Sosok orang yang tampaknya ahli menyembunyikan siapa dirinya bergerak dalam kegelapan.
Namun, ini meyakinkan Sharona bahwa ada orang yang bertanggung jawab atas lelucon tersebut.</color>]],
  ui_story_2002_1_6_dialog_content = "Siapa kamu? Beraninya kamu menyentuh ekorku saat aku tidur!",
  ui_story_2002_1_7_dialog_content = "...",
  ui_story_2002_1_8_dialog_content = "Eclipsite? Dari mana asalmu? Para penjaga yang sedang bertugas itu perlu diberi latihan tambahan...",
  ui_story_2002_1_9_dialog_content = "Tunggu dulu... Bau aneh ini... Ada bau yang lain.",
  ui_story_2002_1_10_dialog_content = "Hei! Kamu Eclipsite atau Aurorian? Aku beri kamu waktu satu menit untuk menjawab, jadi katakan sesuatu jika kamu mengerti!",
  ui_story_2002_1_11_dialog_content = "... Kenapa kau menyerang ekorku?",
  ui_story_2002_1_12_dialog_content = "Jawab dan mungkin saja aku akan membiarkanmu hidup untuk sementara.",
  ui_story_2002_1_13_dialog_content = "<color=#e8d9bb>Sosok itu tetap bersembunyi, mengeluarkan suara yang tak bisa dimengerti, dalam kegelapan.</color>",
  ui_story_2002_1_14_dialog_content = "Kita benar-benar tak bisa berkomunikasi. Sepertinya kamu Eclipsite, jadi jangan salahkan aku karena ini—",
  ui_story_2002_1_15_dialog_content = "... Hahahahaha...",
  ui_story_2002_1_16_dialog_content = "K-kau tertawa? Kamu ini apa? Kamu mengerti aku?",
  ui_story_2002_1_17_dialog_content = "Hahaha... Ahahahaha! Kamu imut juga ternyata kalau sedang bingung...",
  ui_story_2002_1_18_dialog_content = "Aku ingin hadiah darimu saat kita bertemu lagi lain kali—Dah...",
  ui_story_2002_1_19_dialog_content = "Bahasa Universese?! Tunggu!",
  ui_story_2002_1_20_dialog_content = "Argh! Dia sudah pergi.",
  ui_story_2002_1_21_dialog_content = "Bau ini... Seperti bau aura Eclipsite dan... bubuk mesiu?",
  ui_story_2002_1_22_dialog_content = "Argh...",
  ui_story_2002_1_23_dialog_content = "Kau sudah lama di sini? Jadi, apakah makhluk itu bosmu? Dia benar-benar membiarkan bawahannya mati seperti itu? Konyol sekali.",
  ui_story_2002_1_24_dialog_content = "Akan kulampiaskan kekesalanku pada bocah tengil sepertimu hingga aku berhasil menemukan bosmu.",
  ui_story_2002_1_25_dialog_content = "Bom dan Eclipsite itu terlalu lemah... Aku hampir tak mengeluarkan tenagaku melawan mereka.",
  ui_story_2002_1_26_dialog_content = "Sharona? Sedang apa kamu di sini sepagi ini? Kekacauan apa ini... Kau barusan berkelahi dengan seseorang?",
  ui_story_2002_1_27_dialog_content = "Ada antek-antek kegelapan bersembunyi di luar tadi, jadi aku keluar untuk menyingkirkan mereka.",
  ui_story_2002_1_28_dialog_content = "Kau terlihat seperti butuh bantuan. Bagaimana dengan secangkir kopi?",
  ui_story_2002_1_29_dialog_content = "Tak usah... Setelah kupikir lagi, boleh, deh.",
  ui_story_2002_1_30_dialog_content = "Tumben—kamu pasti kurang tidur. Kukira aku mendengar ledakan saat tidur tadi. Kamu yakin semuanya baik-baik saja?",
  ui_story_2002_1_31_dialog_content = "Saat kamu tidur tadi? Kamu bisa berdandan begitu rapi dalam waktu sesingkat itu sebelum bergegas keluar untuk melihat apa yang terjadi? Chief of Staff kita memang hebat.",
  ui_story_2002_1_32_dialog_content = "Oh? Mengejutkan sekali. Terima kasih atas pujianmu. Aku perlu menambahkan gula lagi ke kopimu?",
  ui_story_2002_1_33_dialog_content = "Terserah mau bagaimana, aku tak begitu peduli. Omong-omong, bisakah kamu meminta semua berkumpul di sini?",
  ui_story_2002_1_34_dialog_content = "Oh? Sepertinya ada sesuatu yang penting.",
  ui_story_2002_1_35_dialog_content = "Tidak juga, tapi menurutku ini juga bukan hal yang sederhana. Aku hanya ingin semuanya berjalan dengan lancar.",
  ui_story_2002_1_36_dialog_content = "Tapi aku baru saja melihat ekormu mengibas-ngibas ke tanah dengan tidak sabar. Kamu yakin ini bukan hal yang serius?",
  ui_story_2002_1_37_dialog_content = "... Lupakan yang baru saja kaulihat. Aku tak ingin mengulangi ucapanku lagi.",
  ui_story_2002_1_38_dialog_content = "... Itu saja. Eclipsite tak dikenal itu pasti akan menyerang kita lagi, jadi kita semua harus waspada. Sekian. Rapat selesai.",
  ui_story_2002_1_39_dialog_content = "Aduh... Terlalu banyak orang di sini. Bagaimana aku bisa cukup tidur kalau rapatnya saja sepagi ini?",
  ui_story_2002_1_40_dialog_content = "Kamu terlambat, Philyshy.",
  ui_story_2002_1_41_dialog_content = "Jangan begitu, dong! Aku hanya ketiduran sebentar.",
  ui_story_2002_1_42_dialog_content = "Lima menit lagi? Kamu ingin mengulangi itu?",
  ui_story_2002_1_43_dialog_content = "Tenang, Pak! Seperti kata orang, lima menit pertama dari rapat hanyalah pemanasan. Aku datang tepat waktu untuk hal-hal yang penting...",
  ui_story_2002_1_44_dialog_content = "Dasar... Rapatnya sudah selesai, tahu.",
  ui_story_2002_1_45_dialog_content = "Oh! Benarkah? Meong! Yah, mau bagaimana lagi. Aku akan kembali tidur saja... Sangat mengantuk...",
  ui_story_2002_1_46_dialog_content = "Vivian, ini bawahanmu?",
  ui_story_2002_1_47_dialog_content = "Apa?",
  ui_story_2002_1_48_dialog_content = "Apakah ini bawahanmu?",
  ui_story_2002_1_49_dialog_content = "Oh, eh, ya... Dia bawahanku...",
  ui_story_2002_1_50_dialog_content = "Apa itu perlu ditanyakan? Yang benar saja, Pak, masa kau tidak mengenali rekanmu?",
  ui_story_2002_1_51_dialog_content = "Jaga sikapmu!",
  ui_story_2002_1_52_dialog_content = "Oh! Vivian galak sekali hari ini! Senyum, dong! Kau bisa keriputan jika terlalu sering cemberut, meong.",
  ui_story_2002_1_53_dialog_content = "Aku tak tahu Illumina punya anggota yang pemalas. Bagaimana aku bisa mengingat orang seperti ini? Kamu perlu waktu untuk introspeksi.",
  ui_story_2002_1_54_dialog_content = "Maaf... Aku akan menasihatinya. Jangan marah...",
  ui_story_2002_1_55_dialog_content = "Hei, kenapa aku dimarahi? Aku hanya agak, sedikit terlambat...",
  ui_story_2002_1_56_dialog_content = "Ini konyol! Kamu—",
  ui_story_2002_1_57_dialog_content = [[
Ah! Karena aku sudah membuat kopi, kenapa kita tidak istirahat dulu sejenak dan melupakan hal-hal sepele ini!
... Philyshy, kamu bertugas patroli semalaman hari ini.]],
  ui_story_2002_1_58_dialog_content = "Apa!? Berarti Philyshy... berarti aku tidak bisa t—",
  ui_story_2002_1_59_dialog_content = "Tugas patroli SEMALAMAN! Kamu paham ucapanku? Apakah aku perlu mengulangi ini untuk ketiga kalinya di telingamu?!",
  ui_story_2002_1_60_dialog_content = "Oke, oke—tak perlu berteriak kepada Philyshy... Aku akan melakukannya...",
  ui_story_2002_1_61_dialog_content = "Abaikan dia, Sharona. Meskipun Philyshy sedikit teledor, jangan ragukan kemampuan Reinhardt memilih orang yang berbakat. Aku jamin dia bisa sangat membantu.",
  ui_story_2002_1_62_dialog_content = "Dia bawahanmu, tapi kukira kau perlu tahu itu...",
  ui_story_2002_1_63_dialog_content = "Illumina tidak memerlukan orang yang tak berguna.",
  ui_story_2002_2_1_dialog_content = "...",
  ui_story_2002_2_2_dialog_content = "... Hah?",
  ui_story_2002_2_3_dialog_content = "Aduh! Ekorku!!",
  ui_story_2002_2_4_dialog_content = "...",
  ui_story_2002_2_5_dialog_content = "Ah! Kau lagi! Jika mampu menyusup ke Undercity, kenapa kamu bersusah payah hanya untuk menyerang ekorku dan...?",
  ui_story_2002_2_6_dialog_content = "Ada urusan apa kamu di sini?",
  ui_story_2002_2_7_dialog_content = "...",
  ui_story_2002_2_8_dialog_content = "Hei, jangan-jangan kamu yang mengirimkan sinyal ke yang lainnya? Berhentilah mengobrol dengan teman Eclipsite-mu. Apa gunanya memanggil gerombolan remeh-temeh kemari?",
  ui_story_2002_2_9_dialog_content = "Pintunya terkunci. Kuberi kau waktu satu menit. Jelaskan niatmu, dan aku bisa mempertimbangkan untuk membunuhmu dengan cepat.",
  ui_story_2002_2_10_dialog_content = "... Hahahaha... Tidak sabaran!",
  ui_story_2002_2_11_dialog_content = "Sudah kuduga! Kau berbicara bahasa Universese... Kenapa ada bau Aurorian di badanmu!? Apakah kau Aurorian atau—tidak, dengan aura seperti ini, sudah pasti kamu ini Eclipsite.",
  ui_story_2002_2_12_dialog_content = "Berbaring saja dengan tenang dan biarkan aku mengambil ekormu. Sangat tidak seru kalau kamu begini!",
  ui_story_2002_2_13_dialog_content = "Kamu suka ekorku, ya? Apa? Kalian para Eclipsite memerlukannya untuk tujuan tertentu?",
  ui_story_2002_2_14_dialog_content = "Yah, untuk bermain-main saja.",
  ui_story_2002_2_15_dialog_content = "Hah? Apa... Karena kamu tidak mau mengaku, aku akan menangkap dan menginterogasimu!",
  ui_story_2002_2_16_dialog_content = "Hah! Kau tak bisa menangkapku! Apa karena kamu baru setengah bangun? Sampai jumpa lagi, naga kecil dungu.",
  ui_story_2002_2_17_dialog_content = "Dungu...?! Hei, tunggu! Kamu pikir kamu mau ke mana?!",
  ui_story_2002_2_18_dialog_content = "<color=#e8d9bb>Di luar Intel Room di Illumina</color>",
  ui_story_2002_2_19_dialog_content = "... Di mana dia?",
  ui_story_2002_2_20_dialog_content = "Hah! Kau tepat waktu sekali. Rencananya berjalan sangaaaaat lancar... Hei, omong-omong soal rencana, kamu memintaku untuk mencari apa?\nSesuatu yang sangat kuat dan tangguh—",
  ui_story_2002_2_21_dialog_content = "...sebuah katalis bahan peledak.",
  ui_story_2002_2_22_dialog_content = "Ya, ya, ya, itu dia. Itu dan... ekor naga kecil dungu itu!",
  ui_story_2002_2_23_dialog_content = [[
... Ekor? Hei, sebaiknya kamu jangan bermain-main dan selesaikan misinya. Kamu tahu apa yang akan terjadi jika ada masalah baru yang muncul, 'kan?
Master tidak akan mengampunimu begitu saja!]],
  ui_story_2002_2_24_dialog_content = "Aku, Bowlinger, bertanggung jawab atas bagian terpenting dari rencana Master untuk menghancurkan Illumina. Jika gagal mengembangkan sesuatu yang cukup kuat pada saat kita menyerang—",
  ui_story_2002_2_25_dialog_content = "Ehem, aku hampir saja keceplosan... Apa pun itu, aku ingin kamu menemukan katalis yang bisa meningkatkan dampak serangan!",
  ui_story_2002_2_26_dialog_content = "Bowlinger, kita seharusnya berpartner, jadi kenapa kamu tidak mau berbagi info denganku? Aku harus berusaha keras untuk menemukan \"inti energi\" ini.",
  ui_story_2002_2_27_dialog_content = "Ohhh! Inti energi? Apakah itu teknologi baru Illumina?",
  ui_story_2002_2_28_dialog_content = "... Tunggu, ini bungkusnya? Ini hanya bongkahan emas seukuran telapak tangan!",
  ui_story_2002_2_29_dialog_content = [[
Jangan remehkan bungkusnya! Di dalamnya ada "MAX Bang" Super Core Device dengan kekuatan tak terbatas yang sudah aku rasakan sendiri!
Kamu harus sangat berhati-hati!]],
  ui_story_2002_2_30_dialog_content = "Pastikan tidak membukanya jika kamu belum benar-benar akan menggunakannya karena benda ini tidak stabil. Sebelum kau sadar, benda ini sudah menghilang.",
  ui_story_2002_2_31_dialog_content = "Tidak stabil? Maksudmu, melepaskan energi? Atau mengeluarkan reaksi yang lebih berbahaya?! Aku jadi makin bersemangat!!",
  ui_story_2002_2_32_dialog_content = "Apa pun itu, percayakan saja padaku. Dengan ini, Bowlinger, persiapanmu sudah selesai...",
  ui_story_2002_2_33_dialog_content = [[
Bagus! Aku akan meminta seseorang untuk mengambilnya sekarang! Aku tak menyangka orang yang tidak bisa diandalkan sepertimu bisa berhasil menyelesaikan ini.
Aku akan merekomendasikanmu di hadapan orang itu!]],
  ui_story_2002_2_34_dialog_content = "Wah, terima kasih, Bowlinger. Ingat, jangan buka inti energi ini hingga saat-saat terakhir—",
  ui_story_2002_2_35_dialog_content = "Yang benar saja? Hilang lagi? Bagaimana bisa Eclipsite ini berhasil mendekati kita? Mereka mengambil jalan pintas?",
  ui_story_2002_2_36_dialog_content = "Pemimpin mereka harus bertanggung jawab atas hal ini. Dia sengaja mengirim sekelompok Eclipsite lemah ke sini untuk mati...",
  ui_story_2002_2_37_dialog_content = "Apa dia mencoba memancingku pergi dari sini?! Jika tujuan mereka adalah memancingku agar menjauh dari pintu masuk Undercity,",
  ui_story_2002_2_38_dialog_content = "Maka target mereka yang sebenarnya adalah... Tempat terdekat adalah Intelligence Department, dan satu-satunya yang sedang bertugas malam adalah...",
  ui_story_2002_2_39_dialog_content = "Philyshy!!",
  ui_story_2002_2_40_dialog_content = "Fiuh... Sunyi sekali di sini. Sepertinya belum terjadi apa-apa.",
  ui_story_2002_2_41_dialog_content = "<color=#e8d9bb>Namun, sosok berpakaian putih yang terlihat familier sedang bersandar di pintu terbuka Intel Room dan sepertinya tidak sadarkan diri—</color>",
  ui_story_2002_2_42_dialog_content = "P-Philyshy! Kau baik-baik saja?! Apakah dia diserang...",
  ui_story_2002_2_43_dialog_content = "Panggil para dokter!!",
  ui_story_2002_2_44_dialog_content = "... Jadi, kau cuma tertidur?",
  ui_story_2002_2_45_dialog_content = "... Philyshy... Philyshy sangat mengantuk... Tidak mungkin, Pak, jangan bilang tidur itu melanggar hukum...",
  ui_story_2002_2_46_dialog_content = "Jika kau tidak diserang, kenapa pintu Intel Room terbuka lebar seperti itu...",
  ui_story_2002_2_47_dialog_content = "Hmmm... Philyshy tak tahu...",
  ui_story_2002_2_48_dialog_content = "Bagaimanapun, coba aku periksa apakah kamu terluka.",
  ui_story_2002_2_49_dialog_content = "Tak perlu. Dia baik-baik saja. Dia kucing, tapi dia tidur seperti...",
  ui_story_2002_2_50_dialog_content = "Vivian, kau sudah menemukan orang yang aku jelaskan tadi? Sepertinya juga ada jalan pintas tersembunyi yang bisa digunakan musuh untuk menyembunyikan operasi mereka.",
  ui_story_2002_2_51_dialog_content = "Aku tak menemukan petunjuk apa pun. Jika itu adalah Eclipsite yang bisa lolos darimu, menurutku prajurit biasa tidak akan sanggup melawannya.",
  ui_story_2002_2_52_dialog_content = [[
Aku ingin tahu apa yang dia inginkan... Yang dia lakukan hanyalah membuat kekacauan di dapur Intelligence Department. Sepertinya tidak ada yang hilang,
dan Philyshy juga tidak terluka.]],
  ui_story_2002_2_53_dialog_content = "Aku tak tahu. Orang yang kulihat tadi benar-benar sulit untuk dijelaskan... Aku tak tahu harus bagaimana.",
  ui_story_2002_2_54_dialog_content = "Maaf, aku sangat mengantuk, jadi aku... ketiduran...",
  ui_story_2002_2_55_dialog_content = "Kami tak bermaksud menyalahkanmu, tapi kau... setidaknya bisa lebih serius saat meminta maaf.",
  ui_story_2002_2_56_dialog_content = [[
Ayolah, aku hanya tidur siang... Kamu pasti tahu bahwa aku tak bisa tetap terjaga saat mengantuk,
dan aku bergadang tadi malam.]],
  ui_story_2002_2_57_dialog_content = "Jadi, Intel Room dibobol karena kamu tertidur? Musuh bisa begitu saja masuk dengan bebas?\nBahkan Reinhardt tak akan membelamu jika dia tahu tentang ini—",
  ui_story_2002_2_58_dialog_content = "Eh... Sharona, aku baru saja menghubungi Reinhardt, dan ada beberapa instruksi darinya.",
  ui_story_2002_2_59_dialog_content = "Masalah ini membuatnya khawatir?! I-ini semua salahku... Ini tak akan terjadi jika aku berhasil menangkap makhluk itu... Aku sudah gagal menjalankan tugasku.",
  ui_story_2002_2_60_dialog_content = "Jangan cemas, dia tidak marah. Dia menyuruh kita untuk terus menyelidiki apa yang hilang dan apa tujuan musuh ini.",
  ui_story_2002_2_61_dialog_content = "Aku akan bekerja sama dengannya untuk beberapa pertanyaan internal, tetapi kau harus menindaklanjuti penyelidikan eksternal.",
  ui_story_2002_2_62_dialog_content = "Baiklah. Yakinkan dia bahwa dia bisa memercayakan masalah ini padaku.",
  ui_story_2002_2_63_dialog_content = "Lalu, dia memintamu untuk membawa asisten—",
  ui_story_2002_2_64_dialog_content = "Asisten? Tidak, dia pasti tahu aku mampu menangani ini sendiri. Kenapa dia—",
  ui_story_2002_2_65_dialog_content = "Jangan bilang begitu di saat seperti ini, Sharona. Jika musuh itu terlalu kuat...",
  ui_story_2002_2_66_dialog_content = "Tapi kamu tahu, segalanya akan menjadi lebih buruk jika ada yang menghalangiku.",
  ui_story_2002_2_67_dialog_content = "Tapi, sebenarnya, dia sudah menunjuk seseorang—",
  ui_story_2002_2_68_dialog_content = "<color=#e8d9bb>Kemudian, Vivian menatap Philyshy, yang masih mengantuk, dengan ekspresi yang rumit. Philyshy membeku sesaat sebelum dia sadar.</color>",
  ui_story_2002_2_69_dialog_content = "... Hah? Bos ingin aku pergi??",
  ui_story_2002_2_70_dialog_content = "Ya, kau harus pergi dengan Sharona dan menyelidiki semuanya. Lakukan pekerjaan itu dan kau tidak akan dihukum atas apa yang terjadi hari ini.",
  ui_story_2002_2_71_dialog_content = "<color=#e8d9bb>Sharona dan Philyshy terdiam setelah mendengar ini. Mereka saling melirik, tetapi tak satu pun dari mereka mengatakan sepatah kata pun...</color>",
  ui_story_2002_3_1_dialog_content = "Sharona—tidak, aku harus memanggilmu Leader mulai sekarang, meong! Apa kamu marah?",
  ui_story_2002_3_2_dialog_content = [[
Leader, jangan marah... Aku janji akan membantumu! Leader, kau terlihat begitu kuat!
Aku akan berusaha keras agar bisa menyamaimu!]],
  ui_story_2002_3_3_dialog_content = "Ah! Menyeramkan sekali di sini! Leader, bisakah kau tetap dekat denganku...?",
  ui_story_2002_3_4_dialog_content = "Leader, bagaimana kau bisa menjadi begitu kuat tanpa terlihat terlalu berotot? Apakah ada cara khusus untuk melatih ototmu?",
  ui_story_2002_3_5_dialog_content = "Leader! Tanduk dan ekormu benar-benar menawan! Bolehkah aku menyentuhnya? Boleh, 'kan? Boleh, 'kan?",
  ui_story_2002_3_6_dialog_content = "Huss! Kamu berisik sekali.",
  ui_story_2002_3_7_dialog_content = "Kenapa kamu kesal sekali denganku? Dan kenapa kau berlari begitu kencang? Aku tak bisa mengejarmu! Pelan-pelan!",
  ui_story_2002_3_8_dialog_content = "... Kau tidak merasa bersalah sama sekali? Hal ini tidak akan terjadi jika kamu tidak tertidur saat sedang bertugas—",
  ui_story_2002_3_9_dialog_content = [[
Meong? Maaf, tapi aku sangat mengantuk hari ini, dan aku benar-benar tak bisa tetap terjaga. Belum lagi, kita mendapatkan kesempatan untuk memperbaikinya!
Philyshy tak tahu apa-apa...]],
  ui_story_2002_3_10_dialog_content = "Oh, tidak, mengantuk lagi...",
  ui_story_2002_3_11_dialog_content = "... Tak berguna.",
  ui_story_2002_3_12_dialog_content = "... Oh? Apa itu?",
  ui_story_2002_3_13_dialog_content = "<color=#e8d9bb>Sesuatu menarik perhatian Philyshy. Dia berjalan menuju pertigaan sendirian.</color>",
  ui_story_2002_3_16_dialog_content = "Apakah itu musuh? Hmm, bukan, bukan musuh... Apa aku yang salah?",
  ui_story_2002_3_17_dialog_content = "Kukira baru saja aku merasakan ada sesuatu, tapi auranya menghilang begitu saja...",
  ui_story_2002_3_18_dialog_content = "Sudah tak ada jalan lagi di depan... Hei, Philyshy, kita—",
  ui_story_2002_3_19_dialog_content = "Philyshy?",
  ui_story_2002_3_20_dialog_content = "Dia sudah pergi? Sudah kuduga seharusnya aku tidak mengajaknya!",
  ui_story_2002_3_21_dialog_content = [[
Ah... Aku jadi harus menyelamatkannya dulu sebelum bisa menyelesaikan misi ini. Reinhardt pasti akan memarahiku jika aku meninggalkannya sendiri...
Argh! Merepotkan sekali!]],
  ui_story_2002_3_22_dialog_content = "Hei! Aku dengar semuanya, meong! Kamu bilang akan menyelamatkanku sebelum menyelesaikan misi...",
  ui_story_2002_3_23_dialog_content = "Kamu?!... Lari ke mana kamu tadi?",
  ui_story_2002_3_24_dialog_content = [[
Aku juga tak tahu. Entah bagaimana aku menemukan pintu masuk yang aneh ini! Sepertinya mengarah ke tempat yang aneh.
Ayo kita pergi dari sini!]],
  ui_story_2002_3_25_dialog_content = "Sesuai dugaanku, ada jalan pintas... Bagaimana kamu menemukannya?",
  ui_story_2002_3_26_dialog_content = "Mungkin intuisi kucing? Yang lebih penting, Leader, aku sangat terharu dengan apa yang baru saja kaukatakan, bahwa kamu akan menyelamatkanku dulu—",
  ui_story_2002_3_27_dialog_content = "Aku tidak bilang begitu, kok. Lupakan saja. Ayo bergegas, dan bersiaplah untuk bertarung!",
  ui_story_2002_3_28_dialog_content = "Hehe, kamu tidak bisa mengakuinya saja, meong.",
  ui_story_2002_3_29_dialog_content = [[
Hah?! Jalan pintas ini sangat dekat dengan Undercity! Ini terlihat seperti markas rahasia! Leader, omong-omong apakah kamu menggali lubang saat masih kecil?
Contohnya...]],
  ui_story_2002_3_30_dialog_content = "Diam! Ini bukan tempat bermain, tetap siaga!",
  ui_story_2002_3_31_dialog_content = "Ah! Leader tegas sekali, meong...",
  ui_story_2002_3_32_dialog_content = "Musuhnya lebih sedikit daripada yang kukira. Aku pasti sudah membunuh sebagian besar dari mereka kemarin.",
  ui_story_2002_3_33_dialog_content = "Ah! Leader, awas!",
  ui_story_2002_3_34_dialog_content = "!!!",
  ui_story_2002_3_35_dialog_content = "<color=#e8d9bb>Sharona mengayunkan pedangnya, membelah lawannya menjadi dua di udara. Musuh tak akan bisa mengalahkannya.</color>",
  ui_story_2002_3_36_dialog_content = "Hmmm, kamu kira aku tidak menyadari serangan itu? Aku sudah menarik pedangku saat kamu berbicara, dasar tak berguna...",
  ui_story_2002_3_37_dialog_content = "<color=#e8d9bb>Sharona berbalik dan menyadari—itu tadi baru satu dari dua Eclipsite, dan Philyshy sudah mengalahkan yang satu lagi.</color>",
  ui_story_2002_3_38_dialog_content = "Apa-apaan kau...!",
  ui_story_2002_3_39_dialog_content = "Oh? Leader, maaf. Aku tahu kamu bisa menangani semuanya, meong... Tapi ada satu lagi di belakangmu, jadi aku membantumu.",
  ui_story_2002_3_40_dialog_content = "...Aku tak butuh bantuanmu. Kau hanya perlu melindungi dirimu sendiri.",
  ui_story_2002_3_41_dialog_content = "Jaga dirimu sendiri, tak perlu menjagaku... Aku tak ingin kamu memperlambat gerakku!",
  ui_story_2002_3_42_dialog_content = "Tapi... Ehem, terima kasih.",
  ui_story_2002_3_43_dialog_content = "(Dia menyelamatkanku, meskipun aku hampir salah memahaminya... Sepertinya aku tidak cukup kuat. Aku harus menjadi cukup kuat untuk menangani semuanya sendiri...)",
  ui_story_2002_3_45_dialog_content = "Oh, hmm, aku tak bermaksud lain... Aku hanya...",
  ui_story_2002_3_46_dialog_content = "Pelan-pelan bicaranya... Ayo terus maju.",
  ui_story_2002_3_47_dialog_content = "Baiklah—Philyshy lelah dan mengantuk... Bisakah jalannya agak pelan...",
  ui_story_2002_4_1_dialog_content = "(Jalan pintas ini sangat panjang, tapi tampaknya tidak mengarah ke suatu tempat yang penting dan tidak bisa digunakan untuk bergerak bersama-sama. Aku penasaran jalan pintas ini digunakan untuk apa...)",
  ui_story_2002_4_2_dialog_content = "Hei, Philyshy, sepertinya kita akan segera berhadapan dengan beberapa musuh yang kuat. Kau harus berhati-hati dan bersembunyilah jika bisa.",
  ui_story_2002_4_3_dialog_content = "Aku takut rapier kecilmu tidak akan cukup untuk pertempuran frontal... Hei, dengar tidak?",
  ui_story_2002_4_4_dialog_content = "Leader, maaf... Aku letih sekali... Aku sangat mengantuk, meong...",
  ui_story_2002_4_5_dialog_content = "Apa? Mengantuk? Sekarang?! Yang benar saja? Jangan tertidur, dong!",
  ui_story_2002_4_6_dialog_content = "Oh, tapi aku mengantuk sekali... Philyshy ingin tidur siang. Bagaimana kalau tidur siang sebentar...",
  ui_story_2002_4_7_dialog_content = "Apakah ini terlihat seperti tempat untuk tidur?! Jangan menahanku bahkan jika kamu ingin mati! Aku tidak akan melindungimu!",
  ui_story_2002_4_8_dialog_content = "Kamu akan melindungiku... Kau terlihat galak...",
  ui_story_2002_4_9_dialog_content = "Tapi, sebenarnya kau... sangat... *mendengkur*",
  ui_story_2002_4_10_dialog_content = "Sungguh sulit dipercaya...! Bukankah kau sudah tidur semalaman? Bagaimana bisa kau tertidur begitu saja?!",
  ui_story_2002_4_11_dialog_content = "Ah, dia sudah tidur.",
  ui_story_2002_4_12_dialog_content = "\"Di saat rekan tim yang lemah lengah itulah biasanya kemungkinan besar musuh akan menyerang.\"",
  ui_story_2002_4_13_dialog_content = "Graaaah...!",
  ui_story_2002_4_14_dialog_content = "Tentu saja aku tahu. Hanya bedebah yang menyerang orang saat mereka lengah. Sentuh dia dan tanggung risikonya sendiri.",
  ui_story_2002_4_15_dialog_content = "Tingkat pertempuran ini... Apa kalian hanya main-main? Kebetulan sekali. Ini keahlianku selain bertarung.",
  ui_story_2002_4_16_dialog_content = "Hei, kau! Kenapa belum bangun juga?",
  ui_story_2002_4_17_dialog_content = "Argh... Bagaimana bisa dia tidur nyenyak seperti itu? Sejak kapan Illumina punya anggota seperti dia...",
  ui_story_2002_4_18_dialog_content = "(Cih, cara dia tidur mengingatkanku pada sesuatu... Aku ingin tahu apakah Kakak menatapku dengan cara yang sama saat aku tidur.)",
  ui_story_2002_4_19_dialog_content = "(Bagaimana dia bisa merasa begitu aman menyerahkan keselamatannya di tangan orang lain? Apakah dia bisa seperti ini karena rasa percaya...?)",
  ui_story_2002_4_20_dialog_content = "(Tapi rasanya benar-benar aman pada saat itu.)",
  ui_story_2002_4_21_dialog_content = "Tidak, aku tidak sama seperti dia! Bangun! Sekarang!",
  ui_story_2002_4_22_dialog_content = "... Aku... Aku tidak bisa berjalan lagi... Masih sangat mengantuk...",
  ui_story_2002_4_23_dialog_content = "Bukankah kau sudah tidur tadi malam? Astaga... Yang benar saja? Kau tertidur lagi?!",
  ui_story_2002_5_1_dialog_content = "Jadi, kau di sini, naga dungu.",
  ui_story_2002_5_2_dialog_content = "Hmm? Kau terbangun?",
  ui_story_2002_5_3_dialog_content = "Aku sudah mengawasimu selama... Tunggu, tadi kau memanggilku apa?",
  ui_story_2002_5_4_dialog_content = "Hahaha! Sepertinya kau cukup terbiasa dengan panggilan itu! Kau merindukanku?",
  ui_story_2002_5_5_dialog_content = "Philyshy? Berhenti main-main. Kamu jadi linglung karena terlalu banyak tidur? Sini—",
  ui_story_2002_5_6_dialog_content = "Heh, kau sudah melupakanku? Hahaha! Aku sangat senang bertemu denganmu untuk ketiga kalinya, meong.",
  ui_story_2002_5_7_dialog_content = "Kamu rupanya?! Suara dan baumu berbeda... Kau makhluk itu?!",
  ui_story_2002_5_8_dialog_content = "Hehe, lama juga kamu menyadarinya! Pantas saja karena kamu sudah bertambah tua!",
  ui_story_2002_5_9_dialog_content = [[
<color=#e8d9bb>Mata Sharona menjadi dingin saat tangan kanannya dengan cekatan meraih gagang pedangnya. Makhluk di depannya bukan Philyshy lagi.
Dia yakin akan hal ini.</color>]],
  ui_story_2002_5_10_dialog_content = "... Siapa kau? Jika kau melakukan sesuatu yang tak beralasan, jangan salahkan aku karena menyerangmu!",
  ui_story_2002_5_11_dialog_content = "Kenapa kau tidak menebaknya?",
  ui_story_2002_5_12_dialog_content = "Kamulah iblis licik yang ingin membunuhku saat aku tertidur.",
  ui_story_2002_5_13_dialog_content = "Ahahahahaha! Membunuhmu? Aku hanya menyelesaikan misiku dan ingin mengambil ekormu sekalian. Omong-omong, kamu bisa memanggilku Yumi.",
  ui_story_2002_5_14_dialog_content = "Kenapa kamu ada di tubuh Philyshy... Keluar!",
  ui_story_2002_5_15_dialog_content = "Philyshy? Apa? Aku tidak merasuki tubuh siapa pun.",
  ui_story_2002_5_16_dialog_content = "Tubuh ini milikku sejak awal.",
  ui_story_2002_5_17_dialog_content = "Huh? Jadi, sikapmu yang biasa itu hanya penyamaran? Kamu bersembunyi dalam kegelapan begitu lama, hanya untuk bekerja bagi para Eclipsite?",
  ui_story_2002_5_18_dialog_content = "Penyamaran? Hahahaha! Tidak, tidak, tidak, mana ada yang seperti itu, meong!",
  ui_story_2002_5_19_dialog_content = "Langsung ke intinya dan jujur saja! Jangan salahkan aku yang bersikap kejam jika kamu berani mempermainkanku!",
  ui_story_2002_5_20_dialog_content = "Kejam? Kenapa kau tidak mencobanya kalau begitu, naga dungu!",
  ui_story_2002_5_21_dialog_content = "Hahaha! Boleh juga, dasar naga dungu! Meong!",
  ui_story_2002_5_22_dialog_content = "Hanya kau yang tersisa. Jangan sembunyi, atau aku akan menghancurkan tempat ini untuk menangkapmu!",
  ui_story_2002_5_23_dialog_content = "Oh-ho! Aku menantikannya! Meong!",
  ui_story_2002_5_24_dialog_content = "Cih...",
  ui_story_2002_5_25_dialog_content = "Kamu akan menghampiriku, 'kan?",
  ui_story_2002_5_26_dialog_content = "(Semuanya akan berakhir begitu aku menghabisinya. Dia sudah menyebabkan bencana besar... dan membodohiku juga!)",
  ui_story_2002_5_27_dialog_content = "Kau lelah? Ingin tidur siang?",
  ui_story_2002_5_28_dialog_content = "Diam...",
  ui_story_2002_5_29_dialog_content = "(Hanya perlu satu tebasan dari bahu kiri ke perut kanan... Aku bisa menaklukkannya dengan cepat dari jarak ini...)",
  ui_story_2002_5_30_dialog_content = "Kata-kata dan perilaku Philyshy membuatku merasa bahwa dia adalah dua orang yang berbeda,",
  ui_story_2002_5_31_dialog_content = "tapi bukan itu saja. Terkadang, aku memperhatikan sepertinya dia bisa berkomunikasi dengan Eclipsite.",
  ui_story_2002_5_32_dialog_content = "Vivian, kamu terlalu sensitif tentang ini. Bisa saja kekurangan kepribadian yang biasa. Orang-orang bilang aku juga menakutkan dalam pertempuran...",
  ui_story_2002_5_33_dialog_content = "Aku juga berharap ini sekadar masalah kepribadian saja, tapi sepertinya ini bukan masalah yang biasa.",
  ui_story_2002_5_34_dialog_content = "Lagi pula, Aurorian berkomunikasi dengan Eclipsite? Itu konyol. Kukira aku sudah melenyapkan mereka semua saat perang.",
  ui_story_2002_5_35_dialog_content = "Memang benar, Reinhardt memberitahuku secara langsung. Aku khawatir Philyshy akan melakukan sesuatu yang menyakiti Illumina tanpa menyadarinya, dan akan membuatnya menyesali perbuatannya.",
  ui_story_2002_5_36_dialog_content = "Kalau dia berani melakukan itu,",
  ui_story_2002_5_37_dialog_content = "Aku akan segera menghabisinya.",
  ui_story_2002_5_38_dialog_content = "(Tapi kenapa... Kenapa aku tidak bisa memaksa diriku untuk menyerangnya?)",
  ui_story_2002_5_39_dialog_content = "(Kenapa... Aku hanya perlu menggerakkan pedangku... Sial, lakukan saja, Sharona!)",
  ui_story_2002_5_40_dialog_content = [[
Leader, jangan marah... Aku janji akan membantumu! Leader, kau terlihat begitu kuat!
Aku akan berusaha keras agar bisa menyamaimu!]],
  ui_story_2002_5_41_dialog_content = "Kamu akan melindungiku... Kau terlihat galak... tapi, sebenarnya kau... sangat... *mendengkur*",
  ui_story_2002_5_42_dialog_content = "...*Heh, heh*...",
  ui_story_2002_5_43_dialog_content = "(Jika Reinhardt mengatur semua ini dengan sengaja dan tahu bahwa aku tak akan bisa membunuhmu... Apa yang harus kulakukan...)",
  ui_story_2002_5_44_dialog_content = "...",
  ui_story_2002_5_45_dialog_content = "... Hah?",
  ui_story_2002_5_46_dialog_content = "\"Ekor\"...",
  ui_story_2002_5_47_dialog_content = "Aku tahu!",
  ui_story_2002_5_48_dialog_content = "(Untuk benar-benar melakukan sesuatu seperti ini... Tidak! Ini hanya taktik! Aku harus melakukan apa yang harus kulakukan!)",
  ui_story_2002_5_49_dialog_content = "<color=#e8d9bb>Sharona menarik napas panjang dan tiba-tiba mengempaskan ekornya ke depan.</color>",
  ui_story_2002_5_50_dialog_content = "Bukankah kamu menginginkan ekorku? Ayo, kemari dan ambillah. Tangkap aku dan ekor ini menjadi milikmu.",
  ui_story_2002_5_51_dialog_content = "Meong! A-apa!!!",
  ui_story_2002_5_52_dialog_content = "Ekorku yang lincah dan menyenangkan ada di depanmu! Kamu tidak menginginkannya?!",
  ui_story_2002_5_53_dialog_content = "(Astaga, apa yang sedang kulakukan?!)",
  ui_story_2002_5_54_dialog_content = "Sial! Berani-beraninya! Kau ini—arghhh! Meong!",
  ui_story_2002_5_55_dialog_content = "<color=#e8d9bb>Yumi menerkam ekor Sharona, tetapi Sharona menarik ekornya dengan gesit, menggesernya ke sisi lain tubuhnya sembari berayun ke arah lawannya.—</color>",
  ui_story_2002_5_56_dialog_content = "Benar-benar tertipu... Sebelah sini!",
  ui_story_2002_5_57_dialog_content = "Kena kau!",
  ui_story_2002_5_58_dialog_content = "Mngeeeooong!!!!!!",
  ui_story_2002_5_59_dialog_content = "Apa... Di mana aku... Hah? Leader?",
  ui_story_2002_5_60_dialog_content = "Sepertinya kau sudah kembali normal... Dasar kucing bodoh, kau sudah membuang banyak waktuku.",
  ui_story_2002_5_61_dialog_content = "A-apa yang baru saja terjadi?",
  ui_story_2002_5_62_dialog_content = "... Tak ada. Jangan tanya.",
  ui_story_2002_5_63_dialog_content = "Ah!!! Oh, tidak!!! Aku ingat sekarang!!!",
  ui_story_2002_5_64_dialog_content = "... Apa yang kauingat?! Kau tak boleh memberi tahu siapa pun!!",
  ui_story_2002_5_65_dialog_content = "Hah? Apa itu? Aku baru saja ingat apa yang hilang.",
  ui_story_2002_5_66_dialog_content = "Oh? Hm, baiklah... Apa itu?",
  ui_story_2002_5_67_dialog_content = "Tidak, tepatnya, aku harus bilang bahwa itu adalah sesuatu yang Yumi ambil...",
  ui_story_2002_5_68_dialog_content = "Dasar bodoh! Jangan bilang kamu sudah tahu... Kenapa tidak memberitahuku? Bukankah agak terlambat untuk hanya mengingatnya sekarang?!",
  ui_story_2002_5_69_dialog_content = "Hah? Aku biasanya bertukar dengannya saat sedang tidur, dan mudah kelupaan... Maaf, meong...",
  ui_story_2002_5_70_dialog_content = [[
Aku ingat itu adalah sesuatu yang sangat penting. Warnanya emas, berkilau, dan seukuran telapak tangan. Benda ini benar-benar kuat!
Ini adalah benda berharga yang dijaga kita semua!]],
  ui_story_2002_5_71_dialog_content = [[
Yumi memberikannya kepada seseorang yang tidak kukenal... Tidak, kami saling mengenal, tapi aku tidak tahu siapa itu...
Rasanya seperti mimpi yang tidak bisa kuingat dengan baik...]],
  ui_story_2002_5_72_dialog_content = [[
Lupakan. Aku akan segera mendapatkannya kembali entah apa pun itu. Sementara itu, kamu harus meminta maaf kepadaku sambil menangis setelah kita kembali! Omong-omong...
Siapa Yumi?]],
  ui_story_2002_5_73_dialog_content = "... Dia kucingku. Dulunya adalah partnerku, tapi sekarang, dia adalah aku yang kedua.",
  ui_story_2002_5_74_dialog_content = [[
Seperti yang kamu lihat sendiri, aku tidak begitu kuat, tapi aku menjadi jauh lebih kuat saat bersama Yumi.
Ini yang terjadi di masa lalu dan bahkan sekarang.]],
  ui_story_2002_5_75_dialog_content = "Tapi kemungkinan besar Yumi sudah tidak ada lagi di sini. Mungkin Yumi hidup di hati Philyshy sebagai rasa rinduku padanya.",
  ui_story_2002_5_76_dialog_content = "Mungkin perasaan ini begitu kuat sehingga terkadang aku melakukan hal-hal aneh... Mungkin aku harus ke dokter.",
  ui_story_2002_5_77_dialog_content = "Setelah misi ini selesai, aku akan memberitahumu segalanya tentang masa laluku, oke? Aku punya banyak kisah menarik untuk diceritakan!",
  ui_story_2002_5_78_dialog_content = [[
Kamu... Kamu selalu sangat sulit untuk dimengerti. Lagi pula, kenapa kau menyerangku dengan Eclipsite saat berada dalam kondisi itu?
Rasanya seolah-olah kau akan berbalik melawan kami...]],
  ui_story_2002_5_79_dialog_content = "Oh... Apakah separah itu... Aku minta maaf karena Yumi sudah menimbulkan masalah, Leader. Tolong maafkan dia.",
  ui_story_2002_5_80_dialog_content = "Yumi juga tidak bisa menahannya... Seperti ada suara di kepalaku yang memerintahkan kita untuk melakukan berbagai hal. Setelah kupikir-pikir, sepertinya itu...",
  ui_story_2002_5_81_dialog_content = "... Suara jahat seorang wanita.",
  ui_story_2002_6_1_dialog_content = "Jalan pintas berakhir di sini. Orang yang sudah memanipulasimu mungkin ada di balik pintu ini...",
  ui_story_2002_6_2_dialog_content = "Philyshy! Bagaimana keadaanmu? Kenapa kamu tidak menungguku saja di sini? Aku bisa—",
  ui_story_2002_6_3_dialog_content = "Hei! Jangan manjakan aku seperti itu! Aku sudah benar-benar pulih!",
  ui_story_2002_6_4_dialog_content = "Bagus. Setelah kita keluar dari sini, aku ingin kamu memberi penjelasan yang lebih rinci padaku... Ada hal yang lebih penting yang harus kita lakukan sekarang.",
  ui_story_2002_6_5_dialog_content = "Leader, sepertinya ada aura aneh di dalam...",
  ui_story_2002_6_6_dialog_content = "Kentara sekali. Bau Eclipsite begitu tajam hingga membuatku mual.",
  ui_story_2002_6_7_dialog_content = "Fokus! Aku akan membuka pintunya!",
  ui_story_2002_6_8_dialog_content = "—Siap!",
  ui_story_2002_6_9_dialog_content = "Selamat datang di Great Weapons Institute—karya terhebat dari Bowlinger si hebat dan cerdas, yang sedang berbicara denganmu!",
  ui_story_2002_6_10_dialog_content = "Ada yang bisa kubantu?",
  ui_story_2002_6_11_dialog_content = "Tolong tunjukkan kehebatan dan matilah sekarang juga!",
  ui_story_2002_6_12_dialog_content = "Aku tak begitu paham. Aku lebih suka jika kau bertanya seperti ini padaku:",
  ui_story_2002_6_13_dialog_content = "\"Bowlinger, bisakah kau membunuhku?\"",
  ui_story_2002_6_14_dialog_content = "Tentu saja! Aku akan menyiapkan pemakaman besar untukmu sekarang juga!!",
  ui_story_2002_6_15_dialog_content = "Oh! Leader, aku ingat sekarang!",
  ui_story_2002_6_16_dialog_content = "Sepertinya banyak orang yang penasaran dengan apa yang diingat oleh si imut Philyshy. Nah, apa yang Philyshy ingat?",
  ui_story_2002_6_17_dialog_content = "Biarkan Bowlinger yang menakjubkan ini memberi tahu semua orang apa yang diingat Philyshy. Apa yang Philyshy ingat tentu merupakan pertanyaan besar.",
  ui_story_2002_6_18_dialog_content = "Dan sekian tentang apa yang Philyshy ingat. \nJika tertarik dengan apa yang Philyshy ingat, kau juga bisa—",
  ui_story_2002_6_19_dialog_content = "Diam! Jangan berisik!!",
  ui_story_2002_6_20_dialog_content = "Benda penting itu! Benda itu diberikan kepada... kepada tikus ini!",
  ui_story_2002_6_21_dialog_content = "Kau... kau benar-benar tahu cara menghemat waktuku.",
  ui_story_2002_6_22_dialog_content = [[
Tikus? Beraninya kau menghinaku, Bowlinger yang hebat dan memikat ini!
Aku akan meledakkan kalian semua hingga kalian tidak lebih dari sebuah atom!]],
  ui_story_2002_6_23_dialog_content = "Ehem, kalian para wanita terlalu kuat, dan bahkan aku saja terpaksa mengagumi kalian!",
  ui_story_2002_6_24_dialog_content = "Namun, berkat dukungan Philyshy, aku jadi bisa mengajukan pertanyaan yang sangat penting! Sharona,",
  ui_story_2002_6_25_dialog_content = "Kautahu apa ini? Oh! Bowlinger si cerdas telah mengambil kesempatan untuk menjawab pertanyaan ini! Jawabannya adalah—inti dari sistem energi baru Illumina!\nIni adalah katalis yang kuat!!",
  ui_story_2002_6_26_dialog_content = "Jika aku menggunakannya, seluruh Illumina, tak hanya kalian berdua saja, akan hancur berkeping-keping!!",
  ui_story_2002_6_27_dialog_content = "Awalnya, master memintaku menggali terowongan di bawah Undercity dan meletakkan bubuk mesiu secukupnya untuk menghancurkan fondasinya sebagai persiapan untuk hari di mana dia akan menyerang Illumina!",
  ui_story_2002_6_28_dialog_content = "Di luar dugaan, aku mengalami hambatan dalam risetku. Aku hampir tak bisa mengembangkan senjata pemungkasku untuk menembus sistem pertahanan Gannon!",
  ui_story_2002_6_29_dialog_content = "Hehe! Tapi berkatmu, Philyshy, akhirnya aku bisa! Persona Yumi-mu memberiku katalis yang kubutuhkan!",
  ui_story_2002_6_30_dialog_content = "... Ini...",
  ui_story_2002_6_31_dialog_content = "\"Darkflow digunakan untuk memodifikasi Yumi dan melakukan eksperimen untuk menggabungkannya dengan Philyshy. Dalam terapi trauma psikologis.\"",
  ui_story_2002_6_32_dialog_content = "\"... Kami memanfaatkan tekad lemah milik hewan untuk memanipulasi Philyshy. Perlu pengamatan lebih lanjut... Risiko: Tinggi.\"",
  ui_story_2002_6_33_dialog_content = "Rencana cerdik seperti ini hanya bisa dibuat oleh si hebat— Ehem! Aku hampir saja keceplosan karena terlalu bersemangat!!",
  ui_story_2002_6_34_dialog_content = "Maafkan aku, Leader... Aku...",
  ui_story_2002_6_35_dialog_content = "Huss. Aku tak bisa mengendalikan amarahku sekarang—",
  ui_story_2002_6_36_dialog_content = "Ini semua salah Philyshy... Ini karena aku—",
  ui_story_2002_6_37_dialog_content = "Dasar berengsek! Beraninya kamu memanfaatkan temanku seperti itu!",
  ui_story_2002_6_38_dialog_content = "Hah? Hah? T-teman?",
  ui_story_2002_6_39_dialog_content = "Ya, kalian adalah teman baik! Sebaiknya aku juga akan membunuh teman-teman kalian yang lain di Illumina begitu aku menyingkirkan kalian berdua!",
  ui_story_2002_6_40_dialog_content = [[
Karena kalian para tikus yang beruntung sudah mengetahui tentang rencana master lebih awal,
mungkin sebaiknya aku segera menghancurkan Gannon dan menawarkannya segera kepada master!]],
  ui_story_2002_6_41_dialog_content = "<color=#e8d9bb>Bowlinger dengan cepat memasukkan perangkat emas yang diberikan Yumi ke dalam pangkalan reaktor dan menyalakan daya.</color>",
  ui_story_2002_6_44_dialog_content = "Intinya sudah dimasukkan! Perangkatku yang sangat kuat telah diaktifkan! Lihatlah warnanya yang unik dan bentuknya yang halus!",
  ui_story_2002_6_45_dialog_content = "Tampilannya begitu menakjubkan dan memiliki tekstur yang luar biasa!",
  ui_story_2002_6_46_dialog_content = "Dan ada bau... bau... bau yang memikat ini...?",
  ui_story_2002_6_47_dialog_content = "Kenapa kau menghentikanku untuk menyerangnya? Menurutmu, kita harus berdiri di sini dan menunggu dia membunuh kita, Philyshy?",
  ui_story_2002_6_48_dialog_content = "Tidak! Kau tidak menciumnya, Leader?",
  ui_story_2002_6_49_dialog_content = "... Memang seperti bau... Ehem... busuk... Apakah bau inti energi memang tidak enak?",
  ui_story_2002_6_50_dialog_content = "Ini... Hah? Ikan kaleng?",
  ui_story_2002_6_51_dialog_content = "Oh... Aku ingat sekarang—Yumi sepertinya mengambil sekaleng ikan.",
  ui_story_2002_6_52_dialog_content = "... Jadi, hal sangat penting yang kamu bilang tadi... adalah ikan kaleng?",
  ui_story_2002_6_53_dialog_content = "Ini bukan ikan kaleng biasa! Reinhardt membawanya kemari dari Northland! Ini adalah kaleng ikan herring yang sangat langka!",
  ui_story_2002_6_54_dialog_content = "Baiklah, baiklah, aku paham... Aku tahu kamu ini kucing.",
  ui_story_2002_6_55_dialog_content = "Leader, bisakah kamu mengambil kaleng itu lagi untukku? Aku akan meminta Yumi untuk berhenti mencoba mencuri ekormu sepanjang waktu.",
  ui_story_2002_6_56_dialog_content = "I-i-ikan kaleng?!!! Pembohong! Bah! Argh! Beraninya kamu!!",
  ui_story_2002_6_57_dialog_content = "Beraninya kamu mengolok-olokku seperti ini!! Kamu... argh... akan MENDERITA!! Bagaimana bisa baunya sangat busuk!!!",
  ui_story_2002_6_58_dialog_content = [[
Bahkan jika intinya palsu, rencana ini masih belum sepenuhnya gagal!
Setidaknya aku akan meledakkan tempat ini hingga berkeping-keping! Matilah!!]],
  ui_story_2002_6_59_dialog_content = "Aku akan mengaktifkan instruksi penghancuran diri! Mulai hitungan mundur 10 detik!!",
  ui_story_2002_6_60_dialog_content = "Lari, Leader!!",
  ui_story_2002_6_61_dialog_content = "Kenapa buru-buru? Bukankah dia berkata kita punya waktu 10 detik?",
  ui_story_2002_6_62_dialog_content = "Cepat!",
  ui_story_2002_6_63_dialog_content = "<color=#e8d9bb>6—5—</color>",
  ui_story_2002_6_64_dialog_content = "Aku sedang mencari kalengmu... Berhenti berteriak! Argh... Bau ini!!",
  ui_story_2002_6_65_dialog_content = "<color=#e8d9bb>4—</color>",
  ui_story_2002_6_66_dialog_content = "Dapat. Ulurkan tanganmu. Kita pergi sekarang!",
  ui_story_2002_6_67_dialog_content = "<color=#e8d9bb>3—2—</color>",
  ui_story_2002_6_68_dialog_content = "Ah! Aku jatuh!",
  ui_story_2002_6_69_dialog_content = "Astaga, kau merepotkan sekali, kucing kecil!!",
  ui_story_2002_6_70_dialog_content = "<color=#e8d9bb>1—!</color>",
  ui_story_2002_6_71_dialog_content = "<color=#e8d9bb>Di ujung jalan pintas, kilatan terang dan semburan udara segera menyusul mereka, diikuti dengan gemuruh yang memekakkan telinga.</color>",
  ui_story_2002_6_73_dialog_content = "... Maafkan aku... Ini semua salahku...",
  ui_story_2002_6_74_dialog_content = "Dari awal aku sudah berbahaya, dan sesuatu yang buruk benar-benar terjadi! Huhu! Bahkan bulu di ekorku menjadi keriting karena panas!",
  ui_story_2002_6_75_dialog_content = "Ini bukan waktunya untuk omong kosongmu, dasar bodoh! Ekorku juga hangus!",
  ui_story_2002_6_76_dialog_content = "... Apa pun yang terjadi, jika kau benar-benar khawatir tentang masalahmu, aku akan menemukan cara untuk menyembuhkanmu! Bilang hal seperti itu lagi dan aku akan menampar kepala kucing kecilmu dengan sisi datar pedangku!",
  ui_story_2002_6_77_dialog_content = "Maaf! Aku mulai mengantuk lagi... Leader, aku ingin tidur... Bisakah aku... tidur...",
  ui_story_2002_6_79_dialog_content = "Kau tetap akan tidur bahkan jika aku melarangmu! Lakukan sesukamu saja!",
  ui_story_2002_6_X1_dialog_content = "Aku masih akan melindungimu kali ini...",
  ui_story_2002_6_80_dialog_content = "<color=#e8d9bb>Setelah apinya padam, sosok misterius muncul di antara reruntuhan di area pusat ledakan.</color>",
  ui_story_2002_6_81_dialog_content = "Bowlinger? Apakah situasi yang menyedihkan ini adalah \"rencana sempurna\" tanpa celah yang kaujanjikan kepadaku sebelumnya?",
  ui_story_2002_6_82_dialog_content = "<color=#e8d9bb>Sementara itu, Bowlinger yang sekarat terbaring lemas di reruntuhan, bahkan tak bisa memberi hormat.</color>",
  ui_story_2002_6_83_dialog_content = "\"Benda itu\" adalah ikan kaleng... Kucing sangat sulit ditebak, seharusnya aku tak berharap banyak dari mereka.",
  ui_story_2002_6_84_dialog_content = [[
Schummer jauh lebih bisa diandalkan. Tentu saja, kita terlalu tergesa-gesa mencoba menghancurkan markas besar Illumina ini...
Setidaknya kita sudah mencoba.]],
  ui_story_2002_6_85_dialog_content = "Bowlinger.",
  ui_story_2002_6_86_dialog_content = "... Ya... ehem...",
  ui_story_2002_6_87_dialog_content = "Kau bahkan lebih tak berguna daripada seekor kucing.",
  ui_story_2002_6_88_dialog_content = "Tapi semuanya sudah gagal berkatmu. Kurasa tak ada yang tahu tentang kejadian... ini.",
  ui_story_2002_6_89_dialog_content = "Master, aku... aku akan...",
  ui_story_2002_6_90_dialog_content = "Kau tak perlu menyalahkan dirimu sendiri. Ada begitu banyak pengikut di Eclipse dan rekanmu yang lain akan memenuhi ambisimu menggantikanmu.",
  ui_story_2002_6_91_dialog_content = "Sementara itu, kau dan kucing itu hanyalah kegagalan.",
  ui_story_2002_6_92_dialog_content = "...",
  ui_story_2002_6_93_dialog_content = "Ah! Senang rasanya bisa kembali ke Illumina, meskipun aku tak bisa tinggal lama. Aku penasaran bagaimana kabar <color=#FFB400>teman lamaku</color> sekarang?",
  ui_story_2002_6_94_dialog_content = "Mungkin dia sedang memerintahkan prajurit-prajurit dari posisi tingginya? Atau mungkin dia sedang bersantai dengan tenang di rumahnya, merasa puas dengan kondisinya saat ini...?",
  ui_story_2002_6_95_dialog_content = "R-Reinhardt... jelas bukan tandinganmu, Masterku... Ehem!",
  ui_story_2002_6_96_dialog_content = "Kau tak perlu memberitahuku. Kebencianku membara dalam diam, tapi akan membuat suara yang memekakkan telinga saat rencanaku berhasil. Dia akan mendengarnya suatu hari nanti.",
  ui_story_2002_6_97_dialog_content = "Sementara kamu... Tutuplah matamu. Aku akan membebaskanmu dari kesengsaraanmu. Matahari telah redup—",
  ui_story_2002_6_98_dialog_content = "<color=#e8d9bb>Mata Bowlinger kehilangan secercah cahaya terakhirnya saat dia mengangkat kepalanya dengan lega, dan dia mengucapkan kata-kata terakhirnya yang penuh doa—</color>",
  ui_story_2002_6_99_dialog_content = "—Eclipse akan ada untuk selama-lamanya...",
  ui_story_2003_1_1_dialog_content = "Sejak melihat istana putih yang megah itu, aku tahu di situlah aku seharusnya berada. Itulah <color=#FFB400>rumahku</color>...",
  ui_story_2003_1_2_dialog_content = "Bukan di tempat kumuh dan berantakan seperti <color=#FFB400>Umbraton</color> ini. Aku akan melakukan apa pun untuk...",
  ui_story_2003_1_3_dialog_content = "Meong... meong...",
  ui_story_2003_1_4_dialog_content = "Oh! Aduh!",
  ui_story_2003_1_5_dialog_content = "Hati-hati, Connolly!",
  ui_story_2003_1_6_dialog_content = "Aku tidak sengaja terjatuh lagi... Dasar ceroboh!",
  ui_story_2003_1_7_dialog_content = "<color=#e8d9bb>Pada waktu itu, suatu sore di musim panas. Connolly dan teman Clarinet-nya, Anton, sedang membersihkan ruang bawah tanah Holiday Cafe.</color>",
  ui_story_2003_1_8_dialog_content = "<color=#e8d9bb>Di ruangan kecil berdebu ini, tersembunyi masa lalu Connolly.</color>",
  ui_story_2003_1_9_dialog_content = "Itu semua kertas musik yang kita bawa saat pindah ke sini. Mari lihat...",
  ui_story_2003_1_10_dialog_content = "Aku ingat yang ini! —Dance in E-major— oleh Clarkson... Yang ini —Hymn of the Wind—... dan ini —Litman's Polka—.",
  ui_story_2003_1_11_dialog_content = "Ahh, bukankah ini —Variation on the White Night—? Para Noble suka musik seperti ini, semacam musik paduan suara dengan banyak akord.",
  ui_story_2003_1_12_dialog_content = "Itu namanya kesyahduan.",
  ui_story_2003_1_13_dialog_content = "Kenapa kalian bertengkar? Hati-hati, ini berdebu karena sudah lama tak dibersihkan.",
  ui_story_2003_1_14_dialog_content = "Oh, dan ini...",
  ui_story_2003_1_15_dialog_content = "<color=#e8d9bb>Anton menyerahkan kertas musik polos dengan sampul kuning, bertuliskan hanya satu kata, \"Rumah\", di sudut kanan bawah.</color>",
  ui_story_2003_1_X15_dialog_content = "\"Satu-satunya tempat untuk menyembunyikan semua kegagalan dan kelemahan kita, tempat cinta yang manis.\"",
  ui_story_2003_1_X16_dialog_content = "<color=#FFB400>—Rumah—</color>, istana cinta, kegembiraan, dan kebahagiaan... Manis sekali!",
  ui_story_2003_1_16_dialog_content = "Connolly, kenapa kamu tidak membiarkan ibu mengajarimu cara memainkannya?",
  ui_story_2003_1_17_dialog_content = "Oh, ini... Kukira ini sudah lama hilang. Ini adalah lagu pertama yang diajarkan ibuku untuk dimainkan.",
  ui_story_2003_1_18_dialog_content = "*Bersenandung pelan*",
  ui_story_2003_1_19_dialog_content = "... Bisakah kamu membawakan satu nada dengan selaras?",
  ui_story_2003_1_20_dialog_content = "Emosi adalah kuncinya! Emosiku yang tulus dan penuh semangat!",
  ui_story_2003_1_21_dialog_content = "Tapi aku belum pernah mendengar kamu memainkan lagu ini. Apakah kamu sudah lupa cara memainkannya? Kamu perlu melihat kertas musiknya?",
  ui_story_2003_1_22_dialog_content = "Tidak, ini hanya...",
  ui_story_2003_1_23_dialog_content = "Aku merasa belum sreg untuk memainkannya. Lagi pula, judul lagu ini <color=#FFB400>—Rumah—</color>...",
  ui_story_2003_1_24_dialog_content = "<color=#FFB400>Rumah</color>?",
  ui_story_2003_1_25_dialog_content = "Apakah kau merindukan rumah putih besar itu?",
  ui_story_2003_1_26_dialog_content = "Rumah tua itu?...",
  ui_story_2003_1_27_dialog_content = "Aku lebih memilih Holiday Cafe daripada rumah itu. Di sini ada makanan dan minuman yang lezat... Dan banyak orang aneh juga.",
  ui_story_2003_1_28_dialog_content = "Maaf, aku menyelamu. Connolly, aku mendengar panggilan minta tolong.",
  ui_story_2003_1_29_dialog_content = "Panggilan minta tolong?",
  ui_story_2003_1_30_dialog_content = "Ya, suaranya samar-samar, dan sangat lemah, seperti nyala api yang akan padam...",
  ui_story_2003_1_31_dialog_content = "Aku tak bisa mengabaikannya! Aku tidak boleh... takut! Ayo kita pergi, Anton!",
  ui_story_2003_1_32_dialog_content = "Kita tidak bertanya pada Dayna atau Robyn dulu? Bagaimana jika kita bertemu dengan sekelompok Eclipsite...? Huhu, aku takut!",
  ui_story_2003_1_33_dialog_content = "Tidak apa-apa. Mereka punya kesibukan masing-masing...",
  ui_story_2003_1_34_dialog_content = "Kurasa kita bisa melakukannya sendiri.",
  ui_story_2003_1_35_dialog_content = "Gaah!",
  ui_story_2003_1_36_dialog_content = "*Memainkan klarinet*",
  ui_story_2003_1_37_dialog_content = "Connolly! Kau makin mahir memainkannya!",
  ui_story_2003_1_38_dialog_content = "Bagaimanapun, seperti inilah kehidupan di Umbraton...",
  ui_story_2003_1_39_dialog_content = "Tidak ada penghalang langit dan Eclipsite bisa jadi mengintai di mana saja.",
  ui_story_2003_1_40_dialog_content = "Tadi aku merasa lemah... Tapi, sepertinya aku menjadi lebih kuat sekarang.",
  ui_story_2003_1_41_dialog_content = "Ahh! Ada Dretcher!",
  ui_story_2003_1_42_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_2003_1_43_dialog_content = "D-di mana?!",
  ui_story_2003_1_44_dialog_content = "Hei, aku hanya bercanda!",
  ui_story_2003_1_45_dialog_content = "Aduh! Hati-hati jangan sampai kena tentakelku!",
  ui_story_2003_1_46_dialog_content = "Berhenti menggoda Connolly. Kau tahu, kita ini memang \"saudara\", tapi terkadang kau sangat menyebalkan.",
  ui_story_2003_1_47_dialog_content = "Jadi... Apakah di sini? Ini gelap sekali... Aku tidak menyangka ada lorong-lorong gelap seperti ini di Umbraton.",
  ui_story_2003_1_48_dialog_content = "Ya, aku bisa mendengarnya dengan sangat jelas. Teriakan minta tolongnya sangat berbeda sekarang...",
  ui_story_2003_1_49_dialog_content = "Tapi ini kelihatannya seperti tumpukan kotak tua...",
  ui_story_2003_1_50_dialog_content = "Ha-hatsyii! Banyak sekali debunya... Apakah benar-benar ada orang di bawah sana?",
  ui_story_2003_1_51_dialog_content = "Omong-omong, ayo singkirkan kotak-kotak ini dan cari tahu apa yang ada di bawah sana.",
  ui_story_2003_1_52_dialog_content = "Meong...",
  ui_story_2003_1_53_dialog_content = "Ssttt... Kaudengar itu? Ada sesuatu di sana.",
  ui_story_2003_1_54_dialog_content = "Apa itu yang ada di bawah kotak?...",
  ui_story_2003_1_55_dialog_content = "Pak, kau tidak apa-apa? Jangan khawatir! Kami akan segera mengeluarkanmu... Hei...",
  ui_story_2003_1_56_dialog_content = "Meong... meong...",
  ui_story_2003_1_57_dialog_content = "Begitu, ya...",
  ui_story_2003_1_58_dialog_content = "Seekor <color=#FFB400>kucing</color>?",
  ui_story_2003_2_1_dialog_content = "Cloudrover Guild mungkin tidak terlibat dalam kegiatan amal, tapi praktik tidak jujur semacam itu bisa merusak reputasi kita.",
  ui_story_2003_2_2_dialog_content = "Tikus yang lihai sekali. Dayna, Robyn, pegang dan tarik ekornya.",
  ui_story_2003_2_3_dialog_content = "Sialan, Robyn! Kepung dia!",
  ui_story_2003_2_4_dialog_content = "Tikus ini berani berkeliaran di wilayah kita... Ayo kita tangkap hari ini.",
  ui_story_2003_2_5_dialog_content = "*Mengangguk*",
  ui_story_2003_2_6_dialog_content = "Aku tak percaya ini! Apakah dia melayang? Kencang sekali larinya!",
  ui_story_2003_2_7_dialog_content = "Begitu menangkapnya, aku akan membuatnya berlutut dan memohon belas kasihan...",
  ui_story_2003_2_8_dialog_content = "Atau mungkin memukulinya akan lebih baik!",
  ui_story_2003_2_9_dialog_content = "*Heh... Heh...* Hah... Menyebalkan sekali!",
  ui_story_2003_2_10_dialog_content = "Robyn, di sebelah kirimu!",
  ui_story_2003_2_11_dialog_content = "Tunggu, ini jalan buntu! Bagaimana...",
  ui_story_2003_2_12_dialog_content = "... Dia menghilang.",
  ui_story_2003_2_13_dialog_content = "Aahhhh!",
  ui_story_2003_2_14_dialog_content = "Begitu banyak bajingan ramah yang terkumpul dan terjebak ...",
  ui_story_2003_2_15_dialog_content = "Hei!",
  ui_story_2003_2_16_dialog_content = "*Menebas dengan pedang*",
  ui_story_2003_2_17_dialog_content = "Berengsek! Kita sudah mengejar begitu lama, dan tak ada hasilnya... Aku bisa mendengar bos mengejek kita.",
  ui_story_2003_2_18_dialog_content = "Dan sudah pasti kita tidak akan menerima gaji sekarang. Entah kenapa kepalaku jadi berdenyut-denyut...",
  ui_story_2003_2_19_dialog_content = "Satu hal yang pasti... Pria itu bukan pengusaha biasa.",
  ui_story_2003_2_20_dialog_content = "Kopi...",
  ui_story_2003_2_21_dialog_content = "Kita harus terus bergerak, bahkan jika pekerjaan kita belum selesai.",
  ui_story_2003_2_22_dialog_content = "Mari kita minum kopi di tempat Connolly dan beristirahat.",
  ui_story_2003_2_23_dialog_content = "Silakan, espresso dan susu segar untuk kerja keras kalian.",
  ui_story_2003_2_24_dialog_content = "Mmm! Kopimu tak ada bandingannya, Connolly. Aku sedang dalam dilema sekarang. Aku ingin kau kembali bekerja di Guild, tapi pada saat bersamaan, aku juga tidak bisa berpisah dengan kopi ini...",
  ui_story_2003_2_25_dialog_content = "Jadi, orang itu adalah...",
  ui_story_2003_2_26_dialog_content = "Dia adalah pedagang bersertifikat dari Cloudrover Guild. Kami sudah melacaknya sejak lama. Kamu pernah mendengar tentang <color=#FFB400>White Gold Extract</color>?",
  ui_story_2003_2_27_dialog_content = "<color=#FFB400>White Gold Extract</color>...?",
  ui_story_2003_2_28_dialog_content = "Semacam cairan putih dengan kubus transparan keemasan di dalamnya, agak menyerupai jeli di dalam susu.",
  ui_story_2003_2_29_dialog_content = "Konon katanya, ini bisa digunakan untuk <color=#FFB400>membersihkan garis keturunan, agar orang-orang bisa masuk ke Lumopolis</color>.",
  ui_story_2003_2_30_dialog_content = "Agak sulit dipercaya...",
  ui_story_2003_2_31_dialog_content = "Iya, 'kan? Tapi, bagi mereka yang sudah tinggal lama di Umbraton, bepergian ke Lumopolis adalah sesuatu yang lebih dari sekadar naik pesawat di Shuttle Hub.",
  ui_story_2003_2_32_dialog_content = "Bagi mereka, kedua tempat ini bagaikan dua dunia yang berbeda.",
  ui_story_2003_2_33_dialog_content = "Hmm...",
  ui_story_2003_2_34_dialog_content = "Ekstrak ini bisa memberikan rasa senang, hampir sama dengan kekuatan yang tak ada habisnya. Namun, pada saat yang sama, orang-orang yang meminum ekstrak ini akan terlihat sangat menggiurkan bagi para Eclipsite,",
  ui_story_2003_2_35_dialog_content = "<size=45>dan kemudian, berakhir menjadi mangsa mereka</size>.",
  ui_story_2003_2_36_dialog_content = "Meski demikian, masih banyak orang yang tidak percaya dengan efek samping White Gold Extract ini, dan tergila-gila memburunya.",
  ui_story_2003_2_37_dialog_content = "Pria yang menjual barang ini sama sekali tidak mempedulikan Guild.",
  ui_story_2003_2_38_dialog_content = "... Akan ada korban-korban baru.",
  ui_story_2003_2_39_dialog_content = "Ya...",
  ui_story_2003_2_40_dialog_content = "Oh, kopinya sudah habis.",
  ui_story_2003_2_41_dialog_content = "Tak apa, aku akan membuatnya lagi.",
  ui_story_2003_2_42_dialog_content = "Terima kasih... Kau baik sekali, Connolly.",
  ui_story_2003_2_43_dialog_content = "Oh, iya, aku ingin bertanya sejak aku masuk tadi. Apa itu yang ada di atas meja?",
  ui_story_2003_2_44_dialog_content = "Itu... Erm... Itu robot kucing.",
  ui_story_2003_2_45_dialog_content = "<color=#e8d9bb>Connolly menjelaskan apa yang terjadi kepada Dayna dan Robyn.</color>",
  ui_story_2003_2_46_dialog_content = "Oh... Ternyata robot. Agak aneh, ya. Apakah kucing itu bisa bergerak?",
  ui_story_2003_2_47_dialog_content = "Tidak, tunggu sebentar... Jadi, kamu pergi untuk mengalahkan para Eclipsite? Kenapa kau tidak memberi tahu kami? Bagaimana jika kau berakhir dalam situasi yang berbahaya?",
  ui_story_2003_2_48_dialog_content = "Selalu begitu, pergi sendiri. Semua Eclipsite itu... Kau...",
  ui_story_2003_2_49_dialog_content = "Dayna...",
  ui_story_2003_2_50_dialog_content = "Baiklah, baiklah, aku akan diam... Tapi, beri tahu kami lain kali! Lagi pula, kami ini 'kan <color=#FFB400>keluargamu</color>!",
  ui_story_2003_2_51_dialog_content = "... Ba-baiklah, terserah kamu saja.",
  ui_story_2003_2_52_dialog_content = "Sekarang, beri tahu kami tentang anak kucing itu. Ia bisa apa?",
  ui_story_2003_2_53_dialog_content = "Saat aku menemukannya, kucing itu masih bisa mengeluarkan suara, tetapi sekarang ia benar-benar tak bergerak dan tak bersuara. Mungkin ia sudah... rusak?",
  ui_story_2003_2_54_dialog_content = "Serahkan padaku. Aku ahlinya dalam hal ini.",
  ui_story_2003_2_55_dialog_content = "Hati-hati, ya!",
  ui_story_2003_2_56_dialog_content = "Zzzzsshhh... Meong! Meong!",
  ui_story_2003_2_57_dialog_content = "Wow, kamu benar-benar memperbaikinya!",
  ui_story_2003_2_58_dialog_content = "Apa kubilang?",
  ui_story_2003_2_59_dialog_content = "Ia juga menjilati dirinya sendiri dan menggosokan badannya ke kaki. Oh, waktunya untuk mengelus...",
  ui_story_2003_2_60_dialog_content = [[
Ketemu! Dayna dan Robyn... Kalian menyelinap keluar ke Holiday Cafe selama jam kerja lagi?
Aku harus memotong gaji kalian!]],
  ui_story_2003_2_61_dialog_content = "Sialan, waktunya bekerja. Sampai jumpa lagi, kalau begitu.",
  ui_story_2003_2_62_dialog_content = "... Dah, Connolly.",
  ui_story_2003_2_63_dialog_content = "Oh, ya, lain kali jangan tambahkan gula di espresso...",
  ui_story_2003_2_64_dialog_content = "Sepertinya kita sendirian lagi.",
  ui_story_2003_2_65_dialog_content = "Ya, tapi kita punya anak kucing ini.",
  ui_story_2003_2_66_dialog_content = "Anak kucing itu... Hei, di mana anak kucingnya?",
  ui_story_2003_2_67_dialog_content = "<color=#e8d9bb>Pintu kafe berayun pelan. Makhluk kecil pendiam itu telah menyelinap keluar tanpa ada yang melihatnya.</color>",
  ui_story_2003_3_1_dialog_content = "Ke mana ia pergi?",
  ui_story_2003_3_2_dialog_content = "Jangan khawatir, Connolly. Aku bisa menciumnya.",
  ui_story_2003_3_3_dialog_content = "Apakah ini... Shuttle Hub? Ada di sana!",
  ui_story_2003_3_4_dialog_content = "Warga sipil Umbraton? Dan dari blok paling kotor? Kau bahkan tidak memiliki izin.",
  ui_story_2003_3_5_dialog_content = [[
Meski bukan salah satu dari Noble, aku pernah bekerja untuk mereka! Aku memiliki semua kualifikasi yang diperlukan,
jadi tolong izinkan aku masuk ke Lumopolis, Pak.]],
  ui_story_2003_3_6_dialog_content = "Cukup. Silakan pergi. Jangan menghambat tugas resmi.",
  ui_story_2003_3_7_dialog_content = "Tidak perlu terburu-buru. Hei, kau... Tolong beri tahu kami lebih lanjut tentang kualifikasimu.",
  ui_story_2003_3_8_dialog_content = "Namaku Krane dan aku adalah mekanik yang secara khusus... mempelajari teknologi Lumina dari peradaban kuno.",
  ui_story_2003_3_9_dialog_content = "Kamu pasti pernah mendengar tentangku! Aku pernah tinggal di Lumopolis dan membuat beberapa produk mekanis untuk keluarga Troy! Coba lihat jam tangan ini.",
  ui_story_2003_3_10_dialog_content = "Oh, jam tangan ini lumayan juga.",
  ui_story_2003_3_11_dialog_content = "Jadi...",
  ui_story_2003_3_12_dialog_content = "Tapi Lumopolis tidak membutuhkan gawai yang tak berguna seperti itu.",
  ui_story_2003_3_13_dialog_content = "Krane, tentu saja, kami pernah mendengar nama ini... Mekanik berbakat yang mengaku telah menguasai teknologi peradaban kuno... yang tak lebih dari seorang amatir.",
  ui_story_2003_3_14_dialog_content = "Kau menciptakan kucing bernyanyi dan membawanya ke para Noble, 'kan? Namun, kucing itu ternyata tak bisa bicara. Setelah itu, kau dan kucingmu dibuang dari Lumopolis.",
  ui_story_2003_3_15_dialog_content = "Apa mungkin ini kucingnya?",
  ui_story_2003_3_16_dialog_content = "<color=#e8d9bb>Seekor anak kucing hitam tiba-tiba muncul di kaki si mekanik, duduk dengan patuh dan menatap dengan matanya yang besar.</color>",
  ui_story_2003_3_17_dialog_content = "Tapi, Pak... A-aku juga bisa menunjukkan beberapa kemampuan lain. Aku hanya... tidak bisa memikirkan apa pun sekarang... Sial...",
  ui_story_2003_3_18_dialog_content = "Bagaimanapun, aku akan berusaha sebaik mungkin untuk mendapatkan pekerjaan di Lumopolis.",
  ui_story_2003_3_19_dialog_content = "Pergilah dari sini. Kau sudah cukup membuang waktu kami.",
  ui_story_2003_3_20_dialog_content = "Meong...",
  ui_story_2003_3_21_dialog_content = "Ada apa dengan kucing ini?!",
  ui_story_2003_3_22_dialog_content = "Tangkap kucing itu! Ia menyerang para penjaga dengan ganas. Kita harus membawanya ke Hall of Justice!",
  ui_story_2003_3_23_dialog_content = "Tolong... Pak... Jangan...",
  ui_story_2003_3_24_dialog_content = "Anton!",
  ui_story_2003_3_X24_dialog_content = "Wah! Lumo Guard sedang mencari masalah!",
  ui_story_2003_3_25_dialog_content = "Tapi, tak apa. Connolly, ayo kita buat mereka tidur sekarang.",
  ui_story_2003_3_26_dialog_content = "Akhirnya... Sudah aman! Jangan khawatir, a-aku tidak menyakiti mereka. Aku hanya mengucapkan selamat tidur kepada mereka.",
  ui_story_2003_3_27_dialog_content = "...",
  ui_story_2003_3_28_dialog_content = "Kau baik-baik saja?",
  ui_story_2003_3_29_dialog_content = "Aku hampir mendapatkan kesempatan untuk kembali ke Lumopolis, tapi kau malah muncul dan merusak semuanya!",
  ui_story_2003_3_30_dialog_content = "Meong... meong...",
  ui_story_2003_3_31_dialog_content = "Kau lagi? Kukira kau sudah rusak...",
  ui_story_2003_3_32_dialog_content = [[
Kenapa kau mengikutiku? Aku tidak akan berada di Umbraton jika bukan karenamu, dasar kau...
Aku sudah menjadi tamu para Noble...]],
  ui_story_2003_3_33_dialog_content = "<size=45>Pergi dari hadapanku... Sekarang!</size>",
  ui_story_2003_3_34_dialog_content = "Ah, kau...",
  ui_story_2003_3_35_dialog_content = "Dia pergi...",
  ui_story_2003_3_36_dialog_content = "Kenapa pria itu? Kita sudah membantunya, selain tidak berterima kasih, dia juga meninggalkan kucing kecil malang ini di sini.",
  ui_story_2003_3_37_dialog_content = "Pus... Kau tidak mengikutinya?",
  ui_story_2003_3_38_dialog_content = "Ayah... Ibu? Kalian mau ke mana?",
  ui_story_2003_3_39_dialog_content = "Connolly, maukah kau menunggu kami di sini?",
  ui_story_2003_3_X39_dialog_content = "Kita akan segera kembali ke Lumopolis, rumah kita yang sebenarnya.",
  ui_story_2003_3_X40_dialog_content = "Kamu mungkin akan merasa kesepian...",
  ui_story_2003_3_X41_dialog_content = "Ambillah, ini adalah klarinetku... Harusnya ini bisa sedikit menghiburmu.",
  ui_story_2003_3_X42_dialog_content = "Ini seperti saat itu...",
  ui_story_2003_3_40_dialog_content = "Ia berhenti bergerak, Connolly...",
  ui_story_2003_3_41_dialog_content = "... Sudah kehabisan Lumina...",
  ui_story_2003_3_42_dialog_content = "Hari ini bukan hariku... Kenapa... Kenapa...?",
  ui_story_2003_3_43_dialog_content = "Tidak ada apa-apa selain kebobrokan dan kegelapan. Berjuang dengan makanan murahan yang basi, hidup dalam kemiskinan tanpa akhir.",
  ui_story_2003_3_44_dialog_content = "Aku tak tahan lagi. Aku benci tempat ini. Sudah tak ada yang bisa membuatku bahagia... Aku hanya ingin pulang ke <color=#FFB400>rumah</color>!!!",
  ui_story_2003_3_45_dialog_content = "Kamu ingin pergi ke Lumopolis?",
  ui_story_2003_3_46_dialog_content = "Siapa... siapa itu?!",
  ui_story_2003_3_47_dialog_content = "Kamu tak paham?",
  ui_story_2003_3_48_dialog_content = "Tipuanmu itu hanya bisa membuatmu melangkah ke Lumopolis, tapi tak akan pernah membuatmu melewati batas garis keturunan. Agar bisa tinggal di sana, kamu perlu darah Noble, yang tidak kaumiliki.",
  ui_story_2003_3_49_dialog_content = "Tapi, apa yang bisa kulakukan? Aku terlahir berstatus rendah... Apakah itu artinya aku harus tinggal di tempat sampah ini untuk selamanya?",
  ui_story_2003_3_50_dialog_content = "Kenapa kau tidak mencoba cara lain?",
  ui_story_2003_3_51_dialog_content = "Minumlah ini, dan ini akan memurnikan darahmu dari semua kotoran—lalu kau akan bisa bergabung dengan masyarakat Lumopolis.",
  ui_story_2003_3_52_dialog_content = "Cobalah.",
  ui_story_2003_4_1_dialog_content = "Jadi, kucing ini pernah rusak sebelumnya... Lalu ditinju oleh Dayna, ditendang oleh penjaga, kemudian dibuang oleh pemiliknya.",
  ui_story_2003_4_2_dialog_content = "Sebuah keajaiban kucing ini masih utuh!",
  ui_story_2003_4_3_dialog_content = "Ya... Memang.",
  ui_story_2003_4_4_dialog_content = "Kalau bisa memanfaatkan bakat ini dengan baik, dia pasti bakal menghasilkan banyak uang. Sayang sekali...",
  ui_story_2003_4_5_dialog_content = "Ada banyak orang dengan mimpi tak masuk akal yang ingin menggapai istana putih Lumopolis.",
  ui_story_2003_4_6_dialog_content = "Kudengar jiwa-jiwa malang yang mencoba menyelinap masuk ke Lumopolis melalui Shuttle Hub didorong keluar di tengah jalan dan berakhir lumpuh.",
  ui_story_2003_4_7_dialog_content = "Mereka yang terlalu dekat dengan matahari akan terbakar hingga mati... Kau pernah tinggal di Lumopolis, 'kan?",
  ui_story_2003_4_8_dialog_content = "Aku masih sangat kecil saat itu... dan tidak terlalu suka di sana...",
  ui_story_2003_4_9_dialog_content = "Connolly...",
  ui_story_2003_4_10_dialog_content = "*Menggelengkan kepalanya*",
  ui_story_2003_4_11_dialog_content = "Sedikit lagi dan... Selesai! Hanya itu yang bisa kulakukan.",
  ui_story_2003_4_12_dialog_content = "Tidak, ini hebat. Terima kasih banyak!",
  ui_story_2003_4_13_dialog_content = "<color=#e8d9bb>Kucing robot yang telah diisi ulang itu merapikan dirinya dengan gembira di atas meja dan membenturkan tangan Connolly dengan kepalanya.</color>",
  ui_story_2003_4_14_dialog_content = "Soal biayanya...",
  ui_story_2003_4_15_dialog_content = "Ssst... Meskipun aku mencintai uang dan harta seperti naga, aku tidak mengambil uang begitu saja... Bagaimana dengan secangkir kopi lagi?",
  ui_story_2003_4_16_dialog_content = "Hah?",
  ui_story_2003_4_17_dialog_content = "Apa yang aneh? Sayangku, kamu adalah keluarga kami.",
  ui_story_2003_4_18_dialog_content = "Kamu selalu diterima di keluarga ini...",
  ui_story_2003_4_19_dialog_content = "Sheol, Dayna, Robyn, dan...",
  ui_story_2003_4_20_dialog_content = "Connolly?",
  ui_story_2003_4_21_dialog_content = "Bersemangat dan membersihkan kafenya. Kopi...",
  ui_story_2003_4_22_dialog_content = "Ini milik Dayna? Dia meninggalkannya di sini? Di sini tertulis bahwa...",
  ui_story_2003_4_23_dialog_content = "Korban lain telah membeli ekstrak itu... Krane... Mekanik itu!!",
  ui_story_2003_4_24_dialog_content = "Dia sangat ingin pergi ke Lumopolis... Sekarang dia akan meminum ekstraknya! Bagaimana ini? Kita harus menolongnya!",
  ui_story_2003_4_25_dialog_content = "Tidak, tunggu sebentar...",
  ui_story_2003_4_26_dialog_content = "Beri tahu kami lain kali! Lagi pula, kami ini 'kan <color=#FFB400>keluargamu</color>!",
  ui_story_2003_4_27_dialog_content = "Apa kauingin meninggalkan pesan untuk Dayna?",
  ui_story_2003_4_28_dialog_content = "... Ya. Aku akan menulisnya di papan! \"Untuk Dayna & Robyn, ada korban baru. Aku akan menunggumu di sana.\"",
  ui_story_2003_4_29_dialog_content = "Meong...",
  ui_story_2003_4_30_dialog_content = "Kau tahu tempatnya, 'kan?",
  ui_story_2003_4_31_dialog_content = "Meong... meong...",
  ui_story_2003_4_32_dialog_content = "Ayo kita pergi bersama!",
  ui_story_2003_4_X1_dialog_content = "Minumlah... Minum...",
  ui_story_2003_4_X2_dialog_content = "... Aku sangat... menginginkannya...",
  ui_story_2003_4_X3_dialog_content = "Minumlah dan kau akan menjadi lebih kuat, dan lebih lezat...",
  ui_story_2003_4_X4_dialog_content = "Aku bisa memahami keraguanmu, jadi santai saja... Ingat, kau akan menemukan jalan yang benar pada akhirnya.",
  ui_story_2003_4_33_dialog_content = "Dretcher di mana-mana... Ah, sulit sekali melihat mereka dalam kegelapan... Tidak begitu berbahaya, tapi sangat menyebalkan.",
  ui_story_2003_4_34_dialog_content = "Di sini juga gelap gulita. Sepertinya ini rumahnya. Apakah kita berhasil datang tepat waktu...?",
  ui_story_2003_4_35_dialog_content = "A-ada orang di sini?",
  ui_story_2003_4_36_dialog_content = "Apakah suaraku kurang keras? ADA ORANG DI SINI?",
  ui_story_2003_4_37_dialog_content = "Meong...",
  ui_story_2003_4_38_dialog_content = "Wow, kucing ini bahkan bisa membuka pintu! Ia sudah cukup cerdas untuk menjadi anggota Scale Band kita, ha! Panggil dia, Anton D-minor...",
  ui_story_2003_4_39_dialog_content = "Huss; kita masih belum tahu apa yang sedang terjadi.",
  ui_story_2003_4_40_dialog_content = "Pintunya tidak terkunci...",
  ui_story_2003_4_41_dialog_content = "Oh! Kamu baik-baik saja, Tuan Mekanik?",
  ui_story_2003_4_42_dialog_content = "Meong... meong...",
  ui_story_2003_4_43_dialog_content = "Kamu lagi! Gadis yang suka ikut campur... dan sampah ini. Kenapa kamu di sini?",
  ui_story_2003_4_44_dialog_content = "Tapi, bukan masalah...",
  ui_story_2003_4_X44_dialog_content = "Aku sudah tahu cara masuk ke Lumopolis.",
  ui_story_2003_5_1_dialog_content = "<color=#e8d9bb>Sebuah botol minum kosong tergeletak miring di lantai, sedikit retak karena jatuh, dengan hanya sedikit cairan platinum tersisa di dasar botol.</color>",
  ui_story_2003_5_2_dialog_content = "Aku bisa melihatnya. Aku sedang duduk di dalam sebuah pesawat yang terbang tinggi terbawa angin, dan kemudian, setelah menginjak awan, aku tiba di gerbang depan Lumopolis.",
  ui_story_2003_5_3_dialog_content = "Para malaikat berseragam yang membunyikan trompet mereka untuk menyambutku, dan kemudian mereka membuka gerbang...",
  ui_story_2003_5_4_dialog_content = "Ada juga bangsawan itu, menatapku dengan senyum di wajahnya, yang menggandeng tanganku dan mengantarku ke istana.",
  ui_story_2003_5_5_dialog_content = "Aroma makanan tercium di udara...",
  ui_story_2003_5_6_dialog_content = "Ahhh, ini... ini...",
  ui_story_2003_5_7_dialog_content = "Dia sudah meminumnya...",
  ui_story_2003_5_8_dialog_content = "Tuan Krane... Pak... Anda bisa mendengarku?!",
  ui_story_2003_5_9_dialog_content = "Apakah ini... kehidupan yang kudambakan?",
  ui_story_2003_5_10_dialog_content = "Connolly, awas!",
  ui_story_2003_5_11_dialog_content = "Ahh...",
  ui_story_2003_5_12_dialog_content = "Seperti kata Dayna, dia sudah menjadi umpan para Eclipsite.",
  ui_story_2003_5_13_dialog_content = "Mereka semua tersembunyi di ruangan ini... Arghhh! Ada berapa banyak?!",
  ui_story_2003_5_14_dialog_content = "Mereka mengintai dalam kegelapan, tapi sekarang bukan waktunya untuk bermain petak umpet!",
  ui_story_2003_5_15_dialog_content = "Tetap tenang dan jangan panik...",
  ui_story_2003_5_16_dialog_content = "Anton! Ayo kita bersihkan semua kekacauan ini bersama!",
  ui_story_2003_5_17_dialog_content = "Tapi, kenapa aku merasa begitu... hampa?",
  ui_story_2003_5_18_dialog_content = "Orang itu dengan jelas berkata: Minumlah dan kamu akan terlahir kembali, darah kotormu akan dimurnikan, dan darah bangsawan akan mengalir di nadimu.",
  ui_story_2003_5_19_dialog_content = "Gerbang Lumopolis akan terbuka untukmu, mengarah tidak hanya ke Courtyard, tetapi juga ke Garden di Lumopolis.",
  ui_story_2003_5_20_dialog_content = "Kau akan menyentuh cahaya tempat tertinggi di Lumopolis, dan jiwamu akan menemukan rumahnya.",
  ui_story_2003_5_21_dialog_content = "Tapi, kenapa aku merasa begitu... hampa?",
  ui_story_2003_5_22_dialog_content = "Anak kucingku, yang sudah aku ciptakan dan kembangkan sepanjang hidupku menggunakan pengetahuan hidupku. Apakah kamu akan menjawabku? Kenapa kamu tidak bernyanyi?",
  ui_story_2003_5_23_dialog_content = "Meong...",
  ui_story_2003_5_24_dialog_content = "Yang terakhir! Selesai!",
  ui_story_2003_5_25_dialog_content = "Tuan Krane... Tuan... Bagaimana mungkin?!",
  ui_story_2003_5_26_dialog_content = "<color=#e8d9bb>Para Dretcher yang mengintai di dalam kegelapan tiba-tiba muncul dari kekacauan itu.</color>",
  ui_story_2003_5_27_dialog_content = "<color=#e8d9bb>Mereka menggerogoti lengan mekanik itu, tapi dia bahkan tidak menyadari apa yang sedang terjadi.</color>",
  ui_story_2003_5_28_dialog_content = "Makin banyak Dretcher yang muncul, makin dia terlihat seperti suar yang bersinar, terus-menerus memancing para Eclipsite. Tubuhnya juga terlihat berubah...",
  ui_story_2003_5_29_dialog_content = "Cepat! Ayo kita singkirkan Dretcher sialan ini! Aduh, kotor sekali! Aku tak tahan lagi!",
  ui_story_2003_5_30_dialog_content = "Tak ada rasa sakit, tak ada rasa dingin, tak ada rasa sedih... Ini kehidupan yang kudambakan... Tapi...",
  ui_story_2003_5_31_dialog_content = "Kenapa...",
  ui_story_2003_5_32_dialog_content = "Tuan Krane! Tuan Krane... Jika kita tidak menghentikan ini... Anda akan...",
  ui_story_2003_5_X1_dialog_content = "<color=#FFB400>\"Mati.\"</color>",
  ui_story_2003_5_33_dialog_content = "Kalau begitu... Tak apa. Pada akhirnya, aku belum mencapai kepuasan. Akhirnya, akhirnya...",
  ui_story_2003_5_34_dialog_content = "<color=#e8d9bb>Mekanik itu mengangkat kepalanya sedikit, rapuh bagaikan sehelai kertas, menunggu untuk ditelan oleh Eclipsite.</color>",
  ui_story_2003_5_35_dialog_content = "<color=#e8d9bb>Kucing hitam yang babak belur itu tidak mengeluarkan suara, hanya duduk di sana, menonton dan memahami semua peristiwa yang terjadi.</color>",
  ui_story_2003_6_1_dialog_content = "Apakah kau merindukan Lumopolis, Connolly?",
  ui_story_2003_6_2_dialog_content = "Dinding dan kubah yang tinggi, bangunan-bangunan putih yang diterangi cahaya yang tertinggal, para prajurit menjaga dinding... dan tidak ada Eclipsite.",
  ui_story_2003_6_3_dialog_content = "Itu juga rumah kita.",
  ui_story_2003_6_4_dialog_content = "Tapi bukankah rumah itu tempat di mana ada keluarga? Aku sangat bahagia sekarang, tinggal bersama ibu dan ayah!",
  ui_story_2003_6_5_dialog_content = "Connolly, kau tak paham. Rumah kecil lusuh ini bukanlah rumah kita yang sebenarnya.",
  ui_story_2003_6_6_dialog_content = "Ya... Aku tak paham. Tidak ada perbedaan di antara keduanya.",
  ui_story_2003_6_7_dialog_content = "Tapi Ibu begitu bertekad untuk pergi... Yang kudapatkan akhirnya bukanlah janji untuk kembali ke Lumopolis, melainkan... berita kematian Ibu.",
  ui_story_2003_6_8_dialog_content = "Aku selalu sendiri sejak saat itu, menghabiskan sebagian besar masa kecilku masuk dan keluar dari rumah kerabat, tanpa ada tempat aman yang bisa kusinggahi.",
  ui_story_2003_6_9_dialog_content = "Lumopolis yang megah itu bukanlah rumahku... Aku ingin memberitahu Ibu tentang itu... Kuharap Ibu bisa mendengarku.",
  ui_story_2003_6_10_dialog_content = "(Ratapan yang tak bisa digambarkan)",
  ui_story_2003_6_11_dialog_content = "Apakah transformasinya berhasil?",
  ui_story_2003_6_12_dialog_content = "Wow!!! Apa ini?! Dari mana datangnya para Eclipsite itu? Apa mereka keluar dari sini?",
  ui_story_2003_6_13_dialog_content = "Tapi Anton dan Connolly tak terkalahkan! Bersama, kita bisa...",
  ui_story_2003_6_14_dialog_content = "...",
  ui_story_2003_6_15_dialog_content = "Apa kau diam-diam mau mundur?",
  ui_story_2003_6_16_dialog_content = "Sayang sekali, semua eksperimen sebelumnya gagal. Tapi harusnya kau merasa sedikit berbeda, 'kan? Setelah minum ekstrak yang pekat tadi.",
  ui_story_2003_6_17_dialog_content = "Transformasi... Bukan menjadi Aurorian dari Lumopolis, melainkan mangsa para Eclipsite...",
  ui_story_2003_6_Z17_dialog_content = "Lebih tepatnya, menjadi makanan yang lebih lezat. Daging dan darahmu akan diubah menjadi katalis yang disukai oleh para Eclipsite.",
  ui_story_2003_6_Z18_dialog_content = "Meskipun sayang sekali rencananya tidak berjalan dengan sempurna, akan sia-sia untuk meninggalkan ini pada serangga-serangga yang bodoh itu.",
  ui_story_2003_6_Z19_dialog_content = "Biarkan aku mencicipinya dengan saksama.",
  ui_story_2003_6_Z20_dialog_content = "Eh... Aaaaaaaaah!!!",
  ui_story_2003_6_18_dialog_content = "Tuan Krane!",
  ui_story_2003_6_19_dialog_content = "Eclipsite Level Tinggi! Kau... Apakah kau yang membuat ekstrak sialan ini...?",
  ui_story_2003_6_20_dialog_content = "Tidak, tidak, tidak... Itu tidak mungkin. Aku hanya seorang... pedagang biasa.",
  ui_story_2003_6_21_dialog_content = "Artefak yang begitu hebat dan suci pasti berasal dari Lumopolis yang mulia... Aku hanya sedikit mengembangkannya.",
  ui_story_2003_6_X1_dialog_content = "Kebahagiaan begitu mudah didapat... Berikan kepada orang-orang telantar yang malang itu, tuntunlah mereka menuju kedamaian dan ketenangan...",
  ui_story_2003_6_X2_dialog_content = "Lalu biarkan mereka menjadi apa yang paling kita dambakan.",
  ui_story_2003_6_X3_dialog_content = "Lumopolis... Bagaimana...",
  ui_story_2003_6_X4_dialog_content = "Sayang sekali transformasinya belum selesai. Tapi kurasa rasanya pasti tetap enak.",
  ui_story_2003_6_X5_dialog_content = "Apakah bisa kau tidak mengganggu makanku, gadis manis? Atau kau ingin diubah juga?",
  ui_story_2003_6_X6_dialog_content = "... Aku ingin kau menghentikan kekejaman ini sekarang juga.",
  ui_story_2003_6_X7_dialog_content = "Sayangnya, aku tak bisa memenuhi keinginanmu.",
  ui_story_2003_6_X8_dialog_content = "Aahhhhhh!",
  ui_story_2003_6_X9_dialog_content = "Kuat sekali! Sulit dikendalikan! Ini adalah energi yang sangat berbeda dari Eclipsite lainnya. Darkflow yang begitu padat, seolah-olah ingin menenggelamkan orang di dalamnya.",
  ui_story_2003_6_X10_dialog_content = "Anton...",
  ui_story_2003_6_X11_dialog_content = "Tunggu, Connolly!",
  ui_story_2003_6_X12_dialog_content = "Kau bertindak semaumu sendiri lagi, Connolly.",
  ui_story_2003_6_X13_dialog_content = "Tapi, setidaknya kali ini kamu membuat sedikit kemajuan dan belajar untuk meninggalkan pesan untuk kami di papan.",
  ui_story_2003_6_X14_dialog_content = "<color=#FFB400>\"Keluarga\"</color>.",
  ui_story_2003_6_X15_dialog_content = "Dayna, Robyn! Kalian...",
  ui_story_2003_6_X16_dialog_content = "Kalian akan selalu memiliki tempat yang aman. Ini seperti saat kita pergi ke Holiday Cafe untuk beristirahat dan bersenang-senang.",
  ui_story_2003_6_X17_dialog_content = "Iya!",
  ui_story_2003_6_X18_dialog_content = "Hei, Eclipsite.",
  ui_story_2003_6_X19_dialog_content = [[
Kau sudah menjual barang terlarang dan menyerang anggota Guild... Bagaimana dengan imbalan saat kau melarikan diri, ha?
Kami akan menyelesaikan masalah denganmu satu per satu hari ini.]],
  ui_story_2003_6_22_dialog_content = "Sudah selesai...",
  ui_story_2003_6_23_dialog_content = "Ya... Fiuh.",
  ui_story_2003_6_24_dialog_content = "Anak kucingnya...",
  ui_story_2003_6_25_dialog_content = "... Pluto...",
  ui_story_2003_6_26_dialog_content = "Meong, meong...",
  ui_story_2003_6_27_dialog_content = "Beri mereka waktu sejenak.",
  ui_story_2003_6_28_dialog_content = "*Mulai Bersenandung*",
  ui_story_2003_6_29_dialog_content = "Ini <color=#FFB400>—Rumah—</color>.",
  ui_story_2003_6_30_dialog_content = "Lagu yang diajarkan ibumu?",
  ui_story_2003_6_31_dialog_content = "Ya, kami tinggal di Umbraton saat itu, hidup miskin. Meskipun pernah menjadi Noble, hidup kami menjadi lebih buruk daripada kebanyakan orang biasa.",
  ui_story_2003_6_32_dialog_content = "Tapi, aku merasa sangat bahagia karena ada ibu dan ayah ada di sana... Namun, kemudian...",
  ui_story_2003_6_33_dialog_content = "Bagaimana mungkin? Kau jelas bisa bernyanyi...",
  ui_story_2003_6_34_dialog_content = "Jangan-jangan, kamu menolak benyanyi untuk orang-orang itu karena... Kau hanya ingin menyanyikan lagu ini untukku?",
  ui_story_2003_6_35_dialog_content = "Benarkah itu...? Rasanya... kehampaanku telah terisi...",
  ui_story_2003_6_36_dialog_content = "Mi!",
  ui_story_2003_6_37_dialog_content = "... Keluar dari sini. Tempat ini akan runtuh.",
  ui_story_2003_6_38_dialog_content = "Aku juga tak tahu... tapi katanya, dia dari Lumopolis.",
  ui_story_2003_6_39_dialog_content = "Itu benar-benar Lumopolis...",
  ui_story_2003_6_40_dialog_content = "Kau bisa berdiri? Ayo kita pergi bersama...",
  ui_story_2003_6_41_dialog_content = "Tak ada waktu lagi... Tolong, jika bisa, berikan dia rumah.",
  ui_story_2003_6_42_dialog_content = "Rumah... Runtuh...",
  ui_story_2003_6_X42_dialog_content = "Dayna, Robyn... Aku... Aku ingin mengatakan sesuatu.",
  ui_story_2003_6_43_dialog_content = "Aku ingat Lumopolis sebagai tempat yang berhiaskan air mancur, bunga-bunga, dan matahari buatan manusia... Tempat yang bisa disebut sebagai surga.",
  ui_story_2003_6_44_dialog_content = "Namun, aku sadar sekarang bahwa bukan hal-hal dangkal ini yang membuat orang bahagia.",
  ui_story_2003_6_45_dialog_content = "Ketika aku berada di titik terendahku, bukan Garden atau Noble yang menyelamatkanku... Bos yang menyelamatkanku, Tuan Istvan, dan kalian.",
  ui_story_2003_6_46_dialog_content = "Terima kasih... Ayo kita kembali ke kafe dan minum kapucino!",
  ui_story_2003_6_47_dialog_content = "<color=#e8d9bb>Kafe kecil itu tidak menghasilkan uang dan terus-menerus terkena ancaman berbahaya, tetapi kafe itu telah menjadi rumah baru bagi si anak kucing.</color>",
  ui_story_2003_6_48_dialog_content = "Dayna, berhenti memalu itu, kau akan merusaknya.",
  ui_story_2003_6_49_dialog_content = "Hei, aku sedang mencoba memperbaikinya!",
  ui_story_2003_6_50_dialog_content = "*Diam-diam mengeluarkan senjata*",
  ui_story_2003_6_51_dialog_content = "Meong...!!",
  ui_story_2003_6_52_dialog_content = "Hei, kenapa kucing itu lari?",
  ui_story_2003_6_53_dialog_content = "Aku tidak menyangka ciptaan mekanis bisa menunjukkan keinginan yang kuat untuk bertahan hidup dan bisa memukul sekuat itu di saat nyawanya terancam.",
  ui_story_2003_6_54_dialog_content = [[
Yah, aku baru saja akan menunjukkan keterampilan perbaikan baruku. Hah? Di mana kopiku?
Aku ingat belum menyentuhnya...]],
  ui_story_2003_6_55_dialog_content = "*Menyeruput kopi*",
  ui_story_2003_6_56_dialog_content = "Tak apa. Aku akan membuatkanmu kopi lagi.",
  ui_story_2003_6_57_dialog_content = "Hmmm... Aneh. Apakah hantu bisa muncul di siang bolong?",
  ui_story_2003_6_58_dialog_content = "Sebaiknya aku tidak memberi tahu Dayna bahwa Anton yang meminum kopinya.",
  ui_story_2003_6_59_dialog_content = "<color=#e8d9bb>Sementara Connolly, itu juga akan sama.</color>",
  ui_story_2004_1_1_dialog_content = "Aku melihat es dan salju yang tidak pernah mencair, apa pun musimnya.",
  ui_story_2004_1_2_dialog_content = "Bagaikan penghalang, es dan salju itu membuat musuh tetap berada di luar, tapi juga menghalangi jalanku.",
  ui_story_2004_1_3_dialog_content = "Terperangkap dalam jebakan yang kubuat sendiri, tanggung jawabku menempa rantai ikatanku sendiri.",
  ui_story_2004_1_4_dialog_content = "Sekian lama, ini cukup untuk membekukan hati yang membara.",
  ui_story_2004_1_5_dialog_content = "<color=#FFB400>Akulah Ratu Northland, tapi aku juga tahanan di Northland.</color>",
  ui_story_2004_1_6_dialog_content = "Ini parah! Benar-benar parah!",
  ui_story_2004_1_7_dialog_content = "Kiri!",
  ui_story_2004_1_8_dialog_content = "Kanan!",
  ui_story_2004_1_9_dialog_content = "Para Eclipsite benar-benar ganas kali ini.",
  ui_story_2004_1_10_dialog_content = "Lihatlah manusia salju besarku! Jangan biarkan satu pun dari mereka lolos!",
  ui_story_2004_1_11_dialog_content = "Noah, lihat yang di tengah! Sepertinya dia memanggil bala bantuan.",
  ui_story_2004_1_12_dialog_content = "Woogagagagaga!!!",
  ui_story_2004_1_13_dialog_content = "Sepertinya dia memanggil—",
  ui_story_2004_1_14_dialog_content = "Besar sekali...",
  ui_story_2004_1_15_dialog_content = "Besar sekali...",
  ui_story_2004_1_16_dialog_content = "Itu enam kali tinggi Louise.",
  ui_story_2004_1_17_dialog_content = "Apakah semua Eclipsite bisa tumbuh setinggi itu? Menakjubkan sekali...",
  ui_story_2004_1_18_dialog_content = "Sial, tidak kukira ada yang bisa mengalahkan ukuran manusia saljuku. Aku tidak akan pernah melupakan rasa malu ini.",
  ui_story_2004_1_19_dialog_content = "Ah! Ini serangan—",
  ui_story_2004_1_20_dialog_content = "Bukan waktunya untuk bersantai.",
  ui_story_2004_1_21_dialog_content = "Ini seperti lautan Eclipsite yang tak berujung!",
  ui_story_2004_1_22_dialog_content = "Tolong! Kami butuh bantuan! Kami butuh bantuan!",
  ui_story_2004_1_23_dialog_content = "Meminta bantuan—!",
  ui_story_2004_1_24_dialog_content = "Sst... Louise, Noah, tenanglah.",
  ui_story_2004_1_25_dialog_content = "Kalian akan membangunkan kakakku.",
  ui_story_2004_1_26_dialog_content = "Nikinis!",
  ui_story_2004_1_27_dialog_content = "Dan Yang Mulia!",
  ui_story_2004_1_28_dialog_content = "Seperti air pasang, gelombang Eclipsite akan surut.",
  ui_story_2004_1_29_dialog_content = "Mundurlah, mereka sudah ditakdirkan untuk terkubur oleh es dan salju, tanpa meninggalkan jejak sedikit pun.",
  ui_story_2004_1_30_dialog_content = "Mereka semua... membeku.",
  ui_story_2004_1_31_dialog_content = "Seperti tetesan es yang muncul dari tanah!",
  ui_story_2004_1_32_dialog_content = "Setiap kali aku melihat Yang Mulia Ratu menunjukkan kekuatannya yang sesungguhnya, hatiku penuh dengan rasa kagum.",
  ui_story_2004_1_33_dialog_content = "Tetesan es itu sudah pecah dan menghilang tanpa jejak.",
  ui_story_2004_1_34_dialog_content = "Seperti air yang menguap di udara, tidak ada yang tersisa!",
  ui_story_2004_1_35_dialog_content = "Inilah keajaiban Northland.",
  ui_story_2004_1_36_dialog_content = "Eclipsite lainnya mundur. Meskipun bodoh, mereka tahu apa itu rasa takut.",
  ui_story_2004_1_37_dialog_content = "Hei, Eclipsite—",
  ui_story_2004_1_38_dialog_content = "Jangan coba-coba kembali lagi!",
  ui_story_2004_1_39_dialog_content = "Betul! Bertarung benar-benar menghabiskan semua energiku—",
  ui_story_2004_1_40_dialog_content = "Jangan pernah berpikir untuk kembali!",
  ui_story_2004_1_41_dialog_content = "Karena suatu alasan, para bandit ini tampaknya lebih aktif dari biasanya dan bahkan berani melangkah melintasi perbatasan Northland.",
  ui_story_2004_1_42_dialog_content = "Yang Mulia...",
  ui_story_2004_1_43_dialog_content = "Kakak juga terlihat sangat khawatir...",
  ui_story_2004_1_44_dialog_content = "Bayangan bercampur aduk. Ini adalah waktu ketika bintang-bintang saling terjalin...",
  ui_story_2004_1_45_dialog_content = "Tunggu dulu, pemimpinnya belum mati!",
  ui_story_2004_1_46_dialog_content = "Yang Mulia, perlukah kita mengejarnya dan menghajarnya sekali lagi?",
  ui_story_2004_1_47_dialog_content = "Tidak usah—",
  ui_story_2004_1_48_dialog_content = "Selama makhluk itu tidak melewati perbatasan Northland. Es dan saljuku hanya menjaga rakyatku.",
  ui_story_2004_1_49_dialog_content = "<color=#e8d9bb>Bethlehem mengulurkan tangannya, dan kepingan salju jatuh dengan lembut, menyentuh telapak tangannya tapi tidak meleleh.</color>",
  ui_story_2004_1_50_dialog_content = "Sudah turun salju!",
  ui_story_2004_1_51_dialog_content = "Yah, salju memang selalu turun sepanjang tahun di Northland.",
  ui_story_2004_1_52_dialog_content = "Tanahnya tertutup oleh lapisan salju tebal, bak kapas, lembut, dan putih...",
  ui_story_2004_1_53_dialog_content = "Kamu akan membuat menjadi manusia salju siapa kali ini? Bagaimana kalau membuat Louise!",
  ui_story_2004_1_54_dialog_content = "Oke!",
  ui_story_2004_1_55_dialog_content = "Hei, tunggu sebentar!",
  ui_story_2004_1_56_dialog_content = "Yang benar saja!? Louise tidak sekecil itu!",
  ui_story_2004_1_57_dialog_content = "<color=#e8d9bb>Di bawah Aurora, dunia yang tertutup salju ini menjadi sunyi, gema pertempuran pun memudar ditelan oleh udara yang membeku.</color>",
  ui_story_2004_1_58_dialog_content = "Kepingan salju? \"Salju turun bersama kurir dari atas\"...",
  ui_story_2004_1_59_dialog_content = "Nikinis.",
  ui_story_2004_1_60_dialog_content = "Yang Mulia.",
  ui_story_2004_1_61_dialog_content = "Bersiaplah untuk menyambut—",
  ui_story_2004_1_62_dialog_content = "Seorang <color=#FFB400>pengunjung dari negeri lain</color> akan datang.",
  ui_story_2004_2_1_dialog_content = "Carleen, jangan bersikap tidak sopan. Kau mewakili citra dan kehormatan Lumopolis.",
  ui_story_2004_2_2_dialog_content = "Ya, Tuanku. Aku mengerti.",
  ui_story_2004_2_3_dialog_content = "Pergilah sekarang.",
  ui_story_2004_2_4_dialog_content = "Yang Mulia Carleen, di usia yang begitu muda, harus melakukan perjalanan ke negeri yang jauh di Northland...",
  ui_story_2004_2_5_dialog_content = "Para Eclipsite makin bertambah. Dengan situasi di titik kritis seperti itu, ini adalah pilihan yang diperlukan.",
  ui_story_2004_2_6_dialog_content = "Cepat atau lambat, dia akan menanggung semua beban Lumopolis, dan bertanggung jawab atas kehidupan rakyat di Lumopolis...",
  ui_story_2004_2_7_dialog_content = "Semua ini perlu.",
  ui_story_2004_2_8_dialog_content = "Carleen...",
  ui_story_2004_2_9_dialog_content = "*Mengambil napas panjang*",
  ui_story_2004_2_10_dialog_content = "Fyuh...",
  ui_story_2004_2_11_dialog_content = "*Menghela napas panjang*",
  ui_story_2004_2_12_dialog_content = "Kamu gugup?",
  ui_story_2004_2_13_dialog_content = "Aaaah!",
  ui_story_2004_2_14_dialog_content = "Ma-maaf. Ini salahku!",
  ui_story_2004_2_15_dialog_content = "Takut?",
  ui_story_2004_2_16_dialog_content = "Ya, aku sedikit takut... Ini pertama kalinya aku mengunjungi Northland...",
  ui_story_2004_2_17_dialog_content = "Ibu berkata bahwa Northland tertutup es dan salju, \"Kerajaan Es\" yang romantis tapi dingin.",
  ui_story_2004_2_18_dialog_content = "Cahaya kunang-kunang membimbing jiwa-jiwa menuju hutan tidur abadi, dan White Narcissus meratapi nasibnya di tepi danau...",
  ui_story_2004_2_19_dialog_content = "Saat berada di Lumopolis, aku jarang melihat salju.",
  ui_story_2004_2_20_dialog_content = "Aku belum pernah melihat negeri yang beku seperti ini. Begitu indah.",
  ui_story_2004_2_21_dialog_content = "Tapi, saat benar-benar tiba di sini, aku masih merasa sedikit gugup.",
  ui_story_2004_2_22_dialog_content = "*Menarik wajah Carleen*",
  ui_story_2004_2_23_dialog_content = "Ah! Apakah ini... etiket di Northland?",
  ui_story_2004_2_24_dialog_content = "Hehe! Tidak, hanya saja kau imut sekali sampai aku tak kuat menahannya.",
  ui_story_2004_2_25_dialog_content = "Jangan terlalu cemas. Sebagai tamu kehormatan di Northland, semua orang di sini pasti akan memperlakukanmu dengan baik.",
  ui_story_2004_2_26_dialog_content = "Queen of the North... Seperti apa dia?",
  ui_story_2004_2_27_dialog_content = "Yang Mulia Ratu...",
  ui_story_2004_2_28_dialog_content = "Bermartabat? Hebat? Baik hati?",
  ui_story_2004_2_29_dialog_content = "Sulit bagiku untuk menggambarkannya. Kata-kataku sama tandusnya seperti dataran dingin—",
  ui_story_2004_2_30_dialog_content = "Ah, kita sampai! Omong-omong, kau akan tahu begitu melihatnya!",
  ui_story_2004_2_31_dialog_content = "Selamat datang di takhta abadi Northland—",
  ui_story_2004_2_32_dialog_content = "<color=#FFB400>Winter Palace</color>.",
  ui_story_2004_2_33_dialog_content = "(Istana yang megah sekali... Bahkan sepertinya lebih megah dari Lumopolis.)",
  ui_story_2004_2_34_dialog_content = "(Apakah semuanya di sini terbuat dari kristal es...?)",
  ui_story_2004_2_35_dialog_content = "(Betapa halus atau rumitnya, dan es-es ini tidak meleleh.)",
  ui_story_2004_2_36_dialog_content = "Tamu kecil dari jauh, lihatlah ke sini.",
  ui_story_2004_2_37_dialog_content = "Ah!",
  ui_story_2004_2_38_dialog_content = "Yang... Yang Mulia... Selamat siang.",
  ui_story_2004_2_39_dialog_content = "...",
  ui_story_2004_2_40_dialog_content = "Carleen dari Lumopolis... Doa terbaikku bersamamu.",
  ui_story_2004_2_41_dialog_content = "Semoga persahabatan antara kedua negara kita bertahan selamanya, hingga Aurora memudar.",
  ui_story_2004_2_42_dialog_content = "...",
  ui_story_2004_2_43_dialog_content = "(Mengapa Yang Mulia Ratu terdiam? Apakah aku mengatakan sesuatu yang salah?)",
  ui_story_2004_2_44_dialog_content = "<color=#e8d9bb>Bethlehem bangkit dari takhtanya dan berjalan lurus melewati Carleen seolah-olah dia tidak melihatnya. Rasa malu yang canggung membekukan udara.</color>",
  ui_story_2004_2_45_dialog_content = "(Apakah aku benar-benar melakukan sesuatu yang salah...?)",
  ui_story_2004_2_46_dialog_content = "Tamu kecil?",
  ui_story_2004_2_47_dialog_content = "Hah?",
  ui_story_2004_2_48_dialog_content = "Bergegaslah. Yang Mulia Ratu sedang menunggumu di luar pintu.",
  ui_story_2004_2_49_dialog_content = "Ah! Baiklah!",
  ui_story_2004_2_X1_dialog_content = "(Ah, itu dia! Yang Mulia Ratu!)",
  ui_story_2004_2_X2_dialog_content = "(Jangan, jangan gugup. Tenang, Carleen. Tak akan ada masalah.)",
  ui_story_2004_2_X3_dialog_content = "(Seperti latihanmu sebelumnya...)",
  ui_story_2004_2_X4_dialog_content = "Y-Yang Mulia, kami...",
  ui_story_2004_2_50_dialog_content = "Schwartz mengirimmu kemari untuk belajar cara mengayunkan pedang.",
  ui_story_2004_2_51_dialog_content = "Kalau begitu, mari kita mulai sekarang.",
  ui_story_2004_2_X5_dialog_content = "Hah?",
  ui_story_2004_2_52_dialog_content = "E-Eclipsite!? Bagaimana ini bisa...",
  ui_story_2004_2_X52_dialog_content = "Makhluk itu juga memanggil sekutu lainnya...",
  ui_story_2004_2_53_dialog_content = "Jangan khawatir. Ini adalah sihir sang Ratu—ilusi dari es dan salju. Berusahalah sebaik mungkin.",
  ui_story_2004_2_54_dialog_content = "Aahhhh!",
  ui_story_2004_2_X6_dialog_content = "Apakah aku... menang?",
  ui_story_2004_2_X7_dialog_content = "Menurunkan kewaspadaanmu sekarang hanya akan berujung pada kekalahan.",
  ui_story_2004_2_X8_dialog_content = "Hah!?",
  ui_story_2004_2_55_dialog_content = "Oww... Aduh...",
  ui_story_2004_2_56_dialog_content = "Itu saja kemampuanmu?",
  ui_story_2004_2_57_dialog_content = "Maaf, Yang Mulia.",
  ui_story_2004_2_X9_dialog_content = "Gerakan yang tidak terkoordinasi, tidak mudah fokus, dan kebingungan setelah mendapatkan kemenangan sekilas.",
  ui_story_2004_2_58_dialog_content = "Dan pada kenyataannya... kau bahkan tak bisa memecahkan permukaan es.",
  ui_story_2004_2_59_dialog_content = "Jika kau menghadapi Eclipsite yang sesungguhnya, hidupmu sudah berakhir sekarang.",
  ui_story_2004_2_60_dialog_content = "Maaf... maafkan aku...",
  ui_story_2004_2_X60_dialog_content = "Tarik kembali kata-kata tak berguna itu.",
  ui_story_2004_2_61_dialog_content = "Kau lemah... Angin dan salju di Northland akan melahap orang macam kau dalam sekejap.",
  ui_story_2004_2_62_dialog_content = "Jika kau tidak bisa lulus dari tes ini, mungkin Lumopolis benar-benar tempat yang lebih cocok untukmu.",
  ui_story_2004_2_63_dialog_content = "Ibu, Northland ternyata memang negeri yang beku.",
  ui_story_2004_2_64_dialog_content = "Dia seperti anak ayam kecil saja, menggigil diterpa angin dingin...",
  ui_story_2004_2_65_dialog_content = "Kakak sudah tak tahan lagi...",
  ui_story_2004_2_66_dialog_content = "Karena ini adalah satu-satunya cara agar kecemerlangan Lumopolis akan terus hidup.",
  ui_story_2004_2_67_dialog_content = "Mereka bahkan mengirim gadis kecil seperti ini untuk melakukan misi itu. Hal itulah yang benar-benar dilakukan para bangsawan munafik dari Lumopolis.",
  ui_story_2004_3_1_dialog_content = "*Merapikan dokumen di atas meja*",
  ui_story_2004_3_2_dialog_content = "Eclipsite menyerbu Northland bagaikan gelombang gelap.",
  ui_story_2004_3_3_dialog_content = "Aku sudah terlalu sering melihat ini terjadi. Terlalu berbahaya...",
  ui_story_2004_3_4_dialog_content = "Angin dan salju berlumuran darah, kegelapan menggerogoti cahaya...",
  ui_story_2004_3_5_dialog_content = "Aku sudah melihat malam tanpa akhir, seperti lilin terakhir yang ditiup.",
  ui_story_2004_3_6_dialog_content = "Namun, Aurora masih bersinar redup di malam hari...",
  ui_story_2004_3_7_dialog_content = "Meskipun cahayanya berkedip-kedip.",
  ui_story_2004_3_8_dialog_content = "Aku terlalu lelah untuk melanjutkan pemikiranku... Mungkin aku perlu secangkir teh di sore hari.",
  ui_story_2004_3_9_dialog_content = "Ah-hah!",
  ui_story_2004_3_10_dialog_content = "Kak... Aku sangat gugup... Bagaimana jika Eclipsite menyerangnya lagi!?",
  ui_story_2004_3_11_dialog_content = "Aduh... Keringatku membeku... dan tanganku menempel pada senjataku...",
  ui_story_2004_3_X1_dialog_content = "Terus lanjutkan... Jangan menangis.",
  ui_story_2004_3_X2_dialog_content = "Satu kali lagi...",
  ui_story_2004_3_12_dialog_content = "Jadi, apa yang sedang kaulihat, Nikinis?",
  ui_story_2004_3_13_dialog_content = "Selamat siang, Yang Mulia Ratu. Aku sedang melihat Yang Mulia Carleen.",
  ui_story_2004_3_14_dialog_content = "Ice Blossom!",
  ui_story_2004_3_15_dialog_content = "Wooga—",
  ui_story_2004_3_16_dialog_content = "(Tenang... Tetap tenang.)",
  ui_story_2004_3_X3_dialog_content = "(Tinggi... Itu keuntunganku! Aku bisa menyerang bagian bawahnya...)",
  ui_story_2004_3_17_dialog_content = "(Dan memahami kelemahannya juga keuntungan penting! Kelemahannya...)",
  ui_story_2004_3_18_dialog_content = "Ada di sini!!!",
  ui_story_2004_3_19_dialog_content = "Gaah!",
  ui_story_2004_3_20_dialog_content = "Gagal... lagi... Es...",
  ui_story_2004_3_21_dialog_content = "(Kalahkan sekutunya sebelum mengalahkannya...)",
  ui_story_2004_3_22_dialog_content = "(Tapi ia terus memanggil lebih banyak sekutu. Ini seperti dinding besi yang tak bisa ditembus dengan cara apa pun.)",
  ui_story_2004_3_23_dialog_content = "Tapi, aku tak boleh menyerah!",
  ui_story_2004_3_24_dialog_content = "Luka ini terasa sakit, dan... kakiku juga membeku. Kakiku benar-benar membeku kaku.",
  ui_story_2004_3_25_dialog_content = "Tapi, aku tak boleh menyerah... Ayolah—",
  ui_story_2004_3_26_dialog_content = "Ahh!",
  ui_story_2004_3_27_dialog_content = "Wooga?",
  ui_story_2004_3_28_dialog_content = "Ah, terjatuh—memang masih anak-anak.",
  ui_story_2004_3_29_dialog_content = "Sakit...",
  ui_story_2004_3_30_dialog_content = "Bukankah itu Lady Nikinis dan...",
  ui_story_2004_3_31_dialog_content = "Yang Mulia Ratu!",
  ui_story_2004_3_32_dialog_content = "*Melihat ke samping dalam diam*",
  ui_story_2004_3_33_dialog_content = "(Ups! Aku berantakan sekali!)",
  ui_story_2004_3_34_dialog_content = "(Dipenuhi salju, rambut berantakan, dan gaun yang berlumpur...)",
  ui_story_2004_3_35_dialog_content = "(Aku harus bagaimana!?)",
  ui_story_2004_3_36_dialog_content = "Dia tampaknya khawatir tentang penampilannya. Dia sangat imut, seperti manusia salju kecil!",
  ui_story_2004_3_X4_dialog_content = "...",
  ui_story_2004_3_37_dialog_content = "(Beri hormat, mungkin memberi hormat dulu.)",
  ui_story_2004_3_38_dialog_content = "Berkat Es dan Salju besertamu. Selamat siang, Yang Mulia, Lady Nikinis.",
  ui_story_2004_3_39_dialog_content = "Selamat siang, Carleen Muda. Lanjutkan apa yang sedang kaulakukan.",
  ui_story_2004_3_40_dialog_content = "Baiklah!",
  ui_story_2004_3_41_dialog_content = "Aku akan berusaha keras untuk mengalahkannya dan menyelesaikan ujian ini, Yang Mulia!",
  ui_story_2004_3_42_dialog_content = "Jika Yang Mulia bisa menghibur Yang Mulia Carleen, dia pasti akan sangat senang.",
  ui_story_2004_3_43_dialog_content = "Sejak hari itu, dia datang setiap hari untuk mengatasi tantangan ini.",
  ui_story_2004_3_44_dialog_content = "Dia terjatuh, lalu bangkit lagi... Dia terjatuh—",
  ui_story_2004_3_45_dialog_content = "Lalu, dia sudah berdiri sekali lagi.",
  ui_story_2004_3_46_dialog_content = "Bagaimanapun, dia adalah anak yang tidak begitu ahli—tapi dia berhasil membuat kemajuan besar.",
  ui_story_2004_3_47_dialog_content = "...",
  ui_story_2004_3_48_dialog_content = "Kakak juga berpikir begitu.",
  ui_story_2004_3_49_dialog_content = "Menghiburnya? Tak perlu.",
  ui_story_2004_3_50_dialog_content = "Yang Mulia Ratu... sudah pergi.",
  ui_story_2004_4_1_dialog_content = "Mimpi? Kenangan yang begitu jauh...",
  ui_story_2004_4_2_dialog_content = "Shaya.",
  ui_story_2004_4_3_dialog_content = "Suara itu...",
  ui_story_2004_4_4_dialog_content = "Shaya.",
  ui_story_2004_4_5_dialog_content = "Apakah ini mimpi buruk?",
  ui_story_2004_4_6_dialog_content = "Para Eclipsite sudah mendekat. Jika mereka terus menyerbu masuk, habis sudah Northland.",
  ui_story_2004_4_7_dialog_content = "Tapi, Aurora telah memberi kita kesempatan untuk bertahan hidup—kekuatan es dan salju.",
  ui_story_2004_4_8_dialog_content = "<color=#e8d9bb>Kristal es putih berkelap-kelip di telapak tangan wanita itu, dingin sampai ke tulang, berputar-putar dengan aura hari-hari yang telah berlalu.</color>",
  ui_story_2004_4_9_dialog_content = "Rasa dingin dan sejuk mengembun dalam kristal es yang rapuh ini, menyembunyikan kekuatan yang sesungguhnya.",
  ui_story_2004_4_X1_dialog_content = "Begitu dilepaskan, kristal ini akan menghancurkan segalanya dan mengalahkan semua yang berani menyerang tempat ini.",
  ui_story_2004_4_X2_dialog_content = "Hanya saja, harganya juga kolosal...",
  ui_story_2004_4_10_dialog_content = "<color=#FFB400>Aku takut kau tak akan pernah meninggalkan Northland.</color>",
  ui_story_2004_4_X3_dialog_content = "Pedang bermata dua ini sangat tajam. Ketika kau mengalahkan musuhmu, pedang ini akan meninggalkan bekas luka yang tak bisa disembuhkan di tubuh dan pikiranmu.",
  ui_story_2004_4_11_dialog_content = "Waktu tidak meninggalkan bekasnya di wajahmu, tapi akan mengambil segalanya darimu.",
  ui_story_2004_4_12_dialog_content = "Dengan hanya ditemani salju saja, kamu harus menghadapi dunia ini sendirian.",
  ui_story_2004_4_13_dialog_content = "Hah... Hah...",
  ui_story_2004_4_14_dialog_content = "Mereka datang.",
  ui_story_2004_4_15_dialog_content = "Aku sudah tahu—",
  ui_story_2004_4_16_dialog_content = "Pemerintahan dan kekuasaan bukan hanya alat kontrol—tetapi juga menandakan misi penting dan kesulitan yang hebat.",
  ui_story_2004_4_17_dialog_content = "Bahkan jika longsoran salju melanda, ada yang harus menghalangi jalannya, mempertahankan orang-orang di belakangnya.",
  ui_story_2004_4_18_dialog_content = "Aku dengan sukarela memasuki penjara ini dan tak pernah gentar dalam menghadapi kesulitan.",
  ui_story_2004_4_19_dialog_content = "Apa yang akan kaupilih?",
  ui_story_2004_4_20_dialog_content = "Aku memilih tongkat kerajaan.",
  ui_story_2004_4_21_dialog_content = "Aku akan mengendalikan es dan salju, dan menjaga Northland.",
  ui_story_2004_4_22_dialog_content = "Namun, penjara tetaplah penjara.",
  ui_story_2004_4_23_dialog_content = "<color=#e8d9bb>Satu, dua, Eclipsite yang tak terhitung jumlahnya. Bethlehem berdiri sendiri melawan mereka dalam pertempuran tanpa akhir.</color>",
  ui_story_2004_4_24_dialog_content = "<color=#e8d9bb>Akhirnya, dia mengalahkan semua musuhnya dan berjalan maju, lalu melihat Carleen muda berdiri di sana.</color>",
  ui_story_2004_4_25_dialog_content = "Apakah ini bukan hanya mimpiku, tapi juga mimpinya...",
  ui_story_2004_4_26_dialog_content = "Aurora dan Phospherus, dengarlah permohonanku. Aku ingin...",
  ui_story_2004_4_27_dialog_content = "Carleen, apa yang kaulakukan?",
  ui_story_2004_4_28_dialog_content = "Ah! Yang Mulia! Aku berdoa... kepada Aurora.",
  ui_story_2004_4_29_dialog_content = "Kamu berdoa untuk apa?",
  ui_story_2004_4_30_dialog_content = "Aku berdoa untuk...",
  ui_story_2004_4_31_dialog_content = "Yang Mulia, jika aku tidak merahasiakannya, apakah doa itu akan terkabul?",
  ui_story_2004_4_32_dialog_content = "Lebih aman untuk menyimpan rahasia di hatimu, tapi aku lebih memilih untuk menyampaikannya kepada Aurora.",
  ui_story_2004_4_33_dialog_content = "Karena aku melakukan apa yang kukatakan... Aku selalu memegang ucapanku.",
  ui_story_2004_4_34_dialog_content = "Yang Mulia memang luar biasa...",
  ui_story_2004_4_35_dialog_content = "Kalau begitu, aku... Aku juga akan diam-diam memberi tahu Yang Mulia!",
  ui_story_2004_4_36_dialog_content = "Harapanku adalah... untuk menjadi kuat. Untuk menjadi kuat seperti Yang Mulia.",
  ui_story_2004_4_37_dialog_content = "Untuk menjadi kuat...",
  ui_story_2004_4_38_dialog_content = "Aku sangat lemah sekarang...",
  ui_story_2004_4_39_dialog_content = "Entah sejak kapan, tapi sepertinya hidupku tiba-tiba menjadi sangat kacau.",
  ui_story_2004_4_40_dialog_content = "Ibuku sedang sakit, dan aku sudah lama tidak bertemu dengannya.",
  ui_story_2004_4_X4_dialog_content = "Ayahku bermuka masam, seolah-olah dia tak akan pernah tersenyum lagi.",
  ui_story_2004_4_X5_dialog_content = "Belum ada kabar tentang saudariku—",
  ui_story_2004_4_X6_dialog_content = "Aku ingat dia orang yang penuh kasih dan lembut, tapi sekarang wajahnya menjadi samar-samar dalam ingatanku.",
  ui_story_2004_4_41_dialog_content = "Bahkan Lumopolis yang tak bisa dihancurkan sudah mulai runtuh.",
  ui_story_2004_4_X7_dialog_content = "Dinding-dinding kota selalu kuat, tapi sekarang terlihat sangat rapuh di mataku—",
  ui_story_2004_4_42_dialog_content = "Sementara aku tak bisa berbuat apa-apa.",
  ui_story_2004_4_43_dialog_content = "Jika aku sekuat kamu, semua akan baik-baik saja.",
  ui_story_2004_4_44_dialog_content = "Semua akan baik-baik saja? Heh.",
  ui_story_2004_4_45_dialog_content = "Eh? Yang Mulia baru saja tertawa?",
  ui_story_2004_4_46_dialog_content = "Yang Mulia... menertawakanku?",
  ui_story_2004_4_47_dialog_content = "Tidak, doa kecilmu sama berharganya seperti bintang, bersinar terang di malam hari.",
  ui_story_2004_4_48_dialog_content = "(Rasanya dia sedang memujiku!)",
  ui_story_2004_4_49_dialog_content = "Kalau begitu, Yang Mulia berdoa untuk apa?",
  ui_story_2004_4_50_dialog_content = "Yang Mulia sudah sangat kuat. Apakah ada hal lain yang mungkin Yang Mulia inginkan?",
  ui_story_2004_4_51_dialog_content = "Tentu saja ada.",
  ui_story_2004_4_52_dialog_content = "Tentu saja ada sesuatu yang kuinginkan—",
  ui_story_2004_4_53_dialog_content = "Sama seperti yang kauinginkan.",
  ui_story_2004_5_1_dialog_content = "Kiri! Di sebelah kirimu!",
  ui_story_2004_5_2_dialog_content = "Woah! Hampir saja. Sepertinya ada kesempatan!",
  ui_story_2004_5_3_dialog_content = "Ice! Blossom—!",
  ui_story_2004_5_4_dialog_content = "Luar biasa! Carleen, kau sangat kuat!",
  ui_story_2004_5_5_dialog_content = "Latihanmu sudah membuahkan hasil. Sepertinya harapanmu untuk berhadapan dengan pemimpin Eclipsite itu bukan mimpi belaka—",
  ui_story_2004_5_6_dialog_content = "Gaah!!!",
  ui_story_2004_5_7_dialog_content = "Aduh!!",
  ui_story_2004_5_8_dialog_content = "Ah! Jatuh!",
  ui_story_2004_5_9_dialog_content = "Tarik kembali kata-kata itu.",
  ui_story_2004_5_10_dialog_content = "Tidak, tidak apa-apa! Aku masih bisa bertarung!",
  ui_story_2004_5_11_dialog_content = "Hal terpenting adalah untuk sepenuhnya memahami kekuatan Lumina dan menerimanya dengan hati-hati!",
  ui_story_2004_5_12_dialog_content = "Seperti Louise, kekuatan yang memanggilnya adalah Lumina of the Forest.",
  ui_story_2004_5_13_dialog_content = "Jika digunakan dengan benar, itu bisa mengeluarkan kekuatan yang sangat besar.",
  ui_story_2004_5_14_dialog_content = "Sementara Carleen...",
  ui_story_2004_5_15_dialog_content = "Seharusnya dia dapat Water! Lumina itu...",
  ui_story_2004_5_X1_dialog_content = "Bagaimana cara menjelaskannya... Meskipun aku tak bisa melihatnya, aku bisa merasakan rasa bluberi!",
  ui_story_2004_5_16_dialog_content = "Memahami Lumina...",
  ui_story_2004_5_17_dialog_content = "Benar! Gunakan kekuatan pikiranmu untuk merasakannya. Biarkan aku menunjukkannya!",
  ui_story_2004_5_18_dialog_content = "Rasakan... Fokus, fokus—",
  ui_story_2004_5_19_dialog_content = "Rasanya seperti... bau anjing laut panggang. Gosong dan renyah, mendesis dan gurih.",
  ui_story_2004_5_20_dialog_content = "Ah! Aku lapar.",
  ui_story_2004_5_21_dialog_content = "Karena kaubilang begitu, aku juga jadi lapar.",
  ui_story_2004_5_22_dialog_content = "Jangan menatapku. Aku tidak—",
  ui_story_2004_5_23_dialog_content = "Lapar...",
  ui_story_2004_5_24_dialog_content = "Aku juga lapar.",
  ui_story_2004_5_25_dialog_content = "Anak-anak yang baik tidak bisa berbohong.",
  ui_story_2004_5_26_dialog_content = "Yah, sekali lagi, Carleen!",
  ui_story_2004_5_27_dialog_content = "Tunggu hingga kita mengalahkannya... Kita semua akan pergi dan makan makanan enak!",
  ui_story_2004_5_28_dialog_content = "Baik!",
  ui_story_2004_5_29_dialog_content = "Dia jadi berteman dekat dengan Noah dan Louise.",
  ui_story_2004_5_30_dialog_content = "Dia berlatih di sini setiap hari selama sebulan.",
  ui_story_2004_5_31_dialog_content = "Bahkan ketika salju turun dengan lebat, dia datang lebih awal dan berlatih hingga larut malam. Dia adalah gadis yang baik.",
  ui_story_2004_5_32_dialog_content = "Dia terlihat lebih kuat dari sebelumnya. Meskipun kemampuannya masih perlu dipoles, dia sudah belajar cara mengetahui kelemahan Eclipsite.",
  ui_story_2004_5_33_dialog_content = "Kali ini, sepertinya dia akan berhasil.",
  ui_story_2004_5_X33_dialog_content = "Perjalanannya masih sangat panjang, tapi...",
  ui_story_2004_5_34_dialog_content = "Kita akan menunggu dan melihatnya.",
  ui_story_2004_5_35_dialog_content = "Hah?",
  ui_story_2004_5_36_dialog_content = "Apa kau benar-benar sangat terkejut? Sepertinya dalam pikiranmu aku orang yang cukup keras.",
  ui_story_2004_5_37_dialog_content = "Aku tidak begitu menyukai Lumopolis, tapi Carleen—",
  ui_story_2004_5_38_dialog_content = "Seperti katamu, dia gadis yang baik.",
  ui_story_2004_5_39_dialog_content = "Serangan terakhir!",
  ui_story_2004_5_40_dialog_content = "Di-dia kalah!",
  ui_story_2004_5_41_dialog_content = "Dia kalah!",
  ui_story_2004_5_42_dialog_content = "Makhluk ini menghilang menjadi kepingan salju, membeku sepenuhnya.",
  ui_story_2004_5_43_dialog_content = "Meskipun kepingan salju ini kecil, masing-masing dari kepingan bersifat unik.",
  ui_story_2004_5_44_dialog_content = "Lihat yang heksagonal ini, seperti diiris tipis-tipis. Kepingan ini adalah kristal pipih. Ini seperti lukisan.",
  ui_story_2004_5_45_dialog_content = "Yang ini, dengan titik di kedua ujungnya seperti jarum, adalah kristal bulat.",
  ui_story_2004_5_46_dialog_content = "Kepingan-kepingan salju ini indah. Ini pertama kalinya aku mencermati kepingan salju sejak datang kemari.",
  ui_story_2004_5_47_dialog_content = "Kepingan salju buatan Carleen juga sangat cantik!",
  ui_story_2004_5_X2_dialog_content = "B-benarkah?",
  ui_story_2004_5_X3_dialog_content = "Kepingan salju hanya bisa terbentuk di lingkungan yang sangat dingin.",
  ui_story_2004_5_X4_dialog_content = "Suhu dingin yang bisa membekukanmu!",
  ui_story_2004_5_X5_dialog_content = "Tapi menurutku, untuk kepingan-kepingan salju yang begitu indah, ini sepadan!",
  ui_story_2004_5_X6_dialog_content = "—dan tentu saja aku cukup cerdas untuk mengenakan pakaian supertebal sehingga bisa tetap hangat selagi melihat kepingan-kepingan salju ini.",
  ui_story_2004_5_X7_dialog_content = "Ah, Carleen... Kau kedinginan?",
  ui_story_2004_5_X8_dialog_content = "Se-sedikit.",
  ui_story_2004_5_X9_dialog_content = "Jika kau kedinginan, Noah akan memelukmu. Bagaimana?",
  ui_story_2004_5_X10_dialog_content = "Mmm... Hangat sekali.",
  ui_story_2004_5_48_dialog_content = "Ah! Yang Mulia!",
  ui_story_2004_5_49_dialog_content = "Yang Mulia! Berkat Es dan Salju besertamu.",
  ui_story_2004_5_50_dialog_content = "A-aku sudah mengalahkan para Eclipsite dan menyelesaikan ujian!",
  ui_story_2004_5_51_dialog_content = "Meskipun aku yakin bahwa menurut Yang Mulia performaku belum sempurna... Masih banyak yang bisa diperbaiki.",
  ui_story_2004_5_52_dialog_content = "Dan aku... tidak bisa dibilang sudah bekerja keras...",
  ui_story_2004_5_53_dialog_content = "Aku hanya akan berkata bahwa aku tidak akan pernah puas dengan kekuatanku saat ini! Aku akan terus belajar!",
  ui_story_2004_5_54_dialog_content = "Kenapa kau begitu keras pada dirimu sendiri? Kamu masih sangat muda.",
  ui_story_2004_5_55_dialog_content = "Meskipun aku memberimu ujian yang begitu sulit, kau boleh lari dari ujian itu. Tidak akan ada yang merendahkanmu.",
  ui_story_2004_5_56_dialog_content = "Bahkan ayahmu tidak akan berkata apa-apa.",
  ui_story_2004_5_57_dialog_content = "... Ini semua untuk Lumopolis. Aku ingin mempertahankan rumah kami—tempat rakyatku hidup dalam kebahagiaan.",
  ui_story_2004_5_58_dialog_content = "Jadi, kau datang ke Northland sendirian, tanpa rasa takut di hatimu.",
  ui_story_2004_5_59_dialog_content = "Ya.",
  ui_story_2004_5_X11_dialog_content = "Carleen...",
  ui_story_2004_5_X12_dialog_content = "(Ada sedikit kegelisahan di matanya, tapi ada lebih banyak tekad.)",
  ui_story_2004_5_X13_dialog_content = "(Sementara Joshua, dan tanggung jawab yang harus ditanggungnya, dia tampaknya, bisa dibilang, tahu tentang apa yang akan terjadi di masa depan.)",
  ui_story_2004_5_X14_dialog_content = "(Tapi apa pun masalah yang akan datang padanya, dia sudah siap menghadapinya.)",
  ui_story_2004_5_60_dialog_content = "Dia sedikit mirip denganku. Schwartz bahkan sudah mengantisipasi ini, 'kan? Benar?",
  ui_story_2004_5_61_dialog_content = "Tapi, bukan masalah.",
  ui_story_2004_5_62_dialog_content = "Apa?",
  ui_story_2004_5_63_dialog_content = "Carleen, kau akan menjadi lebih kuat, tapi cepat atau lambat kamu akan mengerti—",
  ui_story_2004_5_64_dialog_content = "Harga dari kekuatan besar adalah kesepian tanpa akhir. Kau akan segera mengetahuinya.",
  ui_story_2004_5_65_dialog_content = "Nah, kenakanlah pakaian hangat dan selamat beristirahat.",
  ui_story_2004_5_66_dialog_content = "Besok kau akan menghadapi ujianmu yang sesungguhnya.",
  ui_story_2004_6_1_dialog_content = "Ini adalah perbatasan Northland. Es dan salju yang kaulihat membentang hingga ribuan mil berhenti di sini.",
  ui_story_2004_6_2_dialog_content = "Di dalam perbatasan ini adalah tempat perlindungan yang dingin, tapi dunia di luar sangat berbahaya dan dipenuhi dengan para Eclipsite.",
  ui_story_2004_6_3_dialog_content = "Lihat. Mereka datang.",
  ui_story_2004_6_4_dialog_content = "Grrrr—",
  ui_story_2004_6_5_dialog_content = "Hah!? Ini sama seperti yang sebelumnya!",
  ui_story_2004_6_6_dialog_content = "Makhluk itu membawa beberapa teman kecil bersamanya. Mungkinkah mereka meremehkan kita?",
  ui_story_2004_6_7_dialog_content = "Tidak—tunggu sebentar...",
  ui_story_2004_6_8_dialog_content = "Di belakangnya... Ada lebih banyak yang mengikutinya...",
  ui_story_2004_6_9_dialog_content = "Ada lebih banyak yang mengikuti di belakang!",
  ui_story_2004_6_10_dialog_content = "Banyak sekali... Apakah para Eclipsite ini gila?",
  ui_story_2004_6_11_dialog_content = "Kau sudah melihat pemimpinnya?",
  ui_story_2004_6_12_dialog_content = "Ia menggunakan kekuatan gelap untuk memanggil anak buahnya dalam usahanya mengotori salju murni.",
  ui_story_2004_6_13_dialog_content = "Carleen, tunjukkan padaku apa yang sudah kamu pelajari beberapa hari terakhir ini. Kalahkan dia.",
  ui_story_2004_6_14_dialog_content = "Apakah... Apakah aku benar-benar bisa melakukannya?",
  ui_story_2004_6_15_dialog_content = "Meskipun ingin menjadi lebih kuat, aku sebenarnya...",
  ui_story_2004_6_16_dialog_content = "Jangan takut. Kau sudah siap untuk ini.",
  ui_story_2004_6_17_dialog_content = "Hah?",
  ui_story_2004_6_19_dialog_content = "Kerja keras akan membuahkan hasil. Percaya pada dirimu sendiri, pada keyakinan dan aspirasimu.",
  ui_story_2004_6_20_dialog_content = "Hah! Yang terakhir!",
  ui_story_2004_6_21_dialog_content = "Kita tidak bisa membiarkan mereka lolos kali ini.",
  ui_story_2004_6_22_dialog_content = "Aku sudah mengurus yang di sebelah sini juga!",
  ui_story_2004_6_23_dialog_content = "Meski tampak seperti gerombolan yang tak terhentikan pada awalnya, ternyata mereka payah sekali.",
  ui_story_2004_6_24_dialog_content = "Yah, siapa yang tahu kapan mereka akan belajar dari kesalahan, meskipun aku tentu saja tidak keberatan melawan mereka.",
  ui_story_2004_6_25_dialog_content = "Aku ingin tahu bagaimana keadaan Carleen...",
  ui_story_2004_6_26_dialog_content = "Ini sudah malam.",
  ui_story_2004_6_27_dialog_content = "(Rasakan kekuatan Light, ya—lihat kelemahan musuh.)",
  ui_story_2004_6_28_dialog_content = "(Ritme, jangan kacaukan ritmenya.)",
  ui_story_2004_6_29_dialog_content = "(Aku tidak bisa mengangkat tanganku lagi, dan wajahku membeku... tapi aku sudah pasti tak akan jatuh sebelum dia kalah!)",
  ui_story_2004_6_30_dialog_content = "(Ini bukan apa-apa, aku sudah tahu semua tipuannya. Tenang... Sedikit demi sedikit...)",
  ui_story_2004_6_31_dialog_content = "Sekarang saatnya!",
  ui_story_2004_6_32_dialog_content = "Carleen! Kamu... kamu berhasil!",
  ui_story_2004_6_33_dialog_content = "Aku mengalahkan, Eclipsite sungguhan, Eclipsite yang sangat kuat... Tak pernah kusangka aku bisa melakukannya.",
  ui_story_2004_6_34_dialog_content = "Kau berhasil melakukannya dengan baik.",
  ui_story_2004_6_35_dialog_content = "<color=#e8d9bb>Bethlehem melangkah maju dan menyentuh kepala Carleen dengan lembut.</color>",
  ui_story_2004_6_36_dialog_content = "Meskipun kekuatan Light lemah sekarang, itu akan menerangi seluruh langit suatu hari nanti.",
  ui_story_2004_6_37_dialog_content = "Carleen, lihatlah.",
  ui_story_2004_6_38_dialog_content = "<color=#e8d9bb>Langit Northland begitu indah, dengan Aurora yang indah melayang di atas, seterang mimpi murni.</color>",
  ui_story_2004_6_39_dialog_content = "Di bawah kegelapan malam, rasanya seperti bisa mengulurkan tanganmu dan menyentuh Aurora yang melayang dengan ringan itu.",
  ui_story_2004_6_40_dialog_content = "Indah sekali...",
  ui_story_2004_6_41_dialog_content = "Northland adalah tempat yang sangat indah, layak mempertaruhkan hidup demi melindunginya.",
  ui_story_2004_6_42_dialog_content = "Dan bagaimana dengan Lumopolis? Lumopolis itu tempat seperti apa bagimu?",
  ui_story_2004_6_43_dialog_content = "Lumopolis terletak tinggi di atas langit, mencurahkan cahayanya dari tempat tinggi.",
  ui_story_2004_6_44_dialog_content = "Ayah, Ibu, para Angel, dan semua orang hebat tinggal di sini.",
  ui_story_2004_6_45_dialog_content = "Di hatiku, tempat itu seindah Northland.",
  ui_story_2004_6_46_dialog_content = "Benarkah?",
  ui_story_2004_6_47_dialog_content = "Aku pernah mendengar dari ayahku bahwa Yang Mulia telah menjaga negeri ini sendiri sejak lama sekali.",
  ui_story_2004_6_48_dialog_content = "Apakah rasanya benar-benar sepi, menjadi begitu kuat?",
  ui_story_2004_6_49_dialog_content = "Ya, benar. Kesepian ini sangat dingin—lebih dingin dari es. Meskipun begitu, aku tak menyesal.",
  ui_story_2004_6_50_dialog_content = "Demi alam Northland yang indah ini, dan Aurora yang indah.",
  ui_story_2004_6_51_dialog_content = "Kamu bisa memahaminya, 'kan?",
  ui_story_2004_6_52_dialog_content = "Aku paham.",
  ui_story_2004_6_X1_dialog_content = "Bahkan jika tidak ada yang memahaminya, bahkan jika aku harus menanggung penderitaan besar, aku harus... menjadi orang itu.",
  ui_story_2004_6_X2_dialog_content = "Dia yang memikul beban dunia dan melindungi semua orang di belakang kita.",
  ui_story_2004_6_X3_dialog_content = "Bahkan jika aku benar-benar sendiri.",
  ui_story_2004_6_53_dialog_content = "Bagus. Carleen, kamu lulus ujian ini.",
  ui_story_2004_6_54_dialog_content = "Selanjutnya, aku akan mengajarimu beberapa keahlian bertarung yang sesungguhnya."
}
return config
